// Bộ ca kiểm thử chức năng viết theo mẫu của môn học (điều kiện trước, bước, dữ liệu nhập, kết quả mong đợi).
// Mỗi ca CHẠY THẬT trên server với MongoDB trong bộ nhớ; kết quả quan sát được ghi ra tools/report-gen/tc-results.json
// để dựng file Excel ca kiểm thử (tools/report-gen/testcase_xlsx.py). Chạy riêng: node --test test/testcases.test.js
process.env.NODE_ENV = 'test';
process.env.SEED_PASSWORD = 'Test@2026';
const { test, before, after } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const mongoose = require('mongoose');
const { MongoMemoryServer } = require('mongodb-memory-server');

let mongod; let server; let base;
const tok = {}; const ids = {};
const PW = 'Test@2026';
const newJar = () => ({ c: '' });
async function api(method, p, { body, token, raw } = {}) {
  const res = await fetch(base + p, {
    method,
    headers: { 'Content-Type': 'application/json', ...(token && token.c ? { Cookie: token.c } : {}) },
    body: body ? JSON.stringify(body) : undefined,
  });
  const sc = res.headers.get('set-cookie');
  if (token && sc) token.c = sc.split(';')[0];
  if (raw) return { status: res.status, text: Buffer.from(await res.arrayBuffer()).toString('utf8'), type: res.headers.get('content-type') };
  const text = await res.text();
  return { status: res.status, body: text ? JSON.parse(text) : null };
}
const login = async (phone, pw = PW) => { const jar = newJar(); const r = await api('POST', '/auth/login', { body: { phone, password: pw }, token: jar }); return { jar, r }; };
const adv = (id, to, t) => api('POST', `/dev/orders/${id}/advance`, { token: t || tok.lan, body: to ? { to } : undefined });
const act = (t, id, a, body) => api('POST', `/seller/orders/${id}/${a}`, { token: t, body });
const money = (n) => Number(n).toLocaleString('vi-VN') + 'đ';

// ------------------------------------------------------------------ khung ca kiểm thử
const CASES = [];
const tc = (mod, id, title, meta, fn) => CASES.push({ mod, id, title, ...meta, fn });
function mkCtx() {
  const lines = [];
  return {
    lines,
    eq(label, actual, expected) { lines.push(`${label}: ${typeof actual === 'string' ? actual : JSON.stringify(actual)}`); assert.deepEqual(actual, expected, `${label}: nhận ${JSON.stringify(actual)}, mong đợi ${JSON.stringify(expected)}`); },
    ok(label, cond, info = '') { lines.push(`${label}${info ? ': ' + info : ''}`); assert.ok(cond, label); },
    note(s) { lines.push(s); },
  };
}

before(async () => {
  mongod = await MongoMemoryServer.create();
  await mongoose.connect(mongod.getUri());
  await require('./fixture')();
  server = require('../src/app').listen(0);
  base = `http://localhost:${server.address().port}/api`;
  const User = mongoose.model('User');
  for (const [k, p] of [['thuy', '0900000001'], ['lan', '0900000002'], ['may', '0900000003'], ['hoa', '0900000004'], ['quoc', '0900000005'], ['linh', '0900000006'], ['admin', '0900000099']]) {
    ids[k] = String((await User.findOne({ phone: p }))._id);
    if (k !== 'linh') tok[k] = (await login(p)).jar;   // 'linh' đăng nhập sau khi được xác minh
  }
  // người bán đã được xác minh: Bếp Cô Lan, Chị Hoa, Quán Nhà Mây, Giặt sấy Mỹ Linh
  const V = require('../src/modules/seller/verification.model');
  for (const k of ['lan', 'hoa', 'may', 'linh']) {
    await V.updateOne({ user: ids[k] }, { $setOnInsert: { user: ids[k], status: 'approved', body: { fullName: k, idNumber: '012345678901', idFront: 'a', idBack: 'b', selfie: 'c', shopName: k, shopType: 'food' } } }, { upsert: true });
  }
  tok.linh = (await login('0900000006')).jar;
  // người kiểm duyệt: tài khoản của Quán Nhà Mây (đồng thời vẫn là người bán đã xác minh)
  await User.updateOne({ phone: '0900000003' }, { role: 'moderator' });
  tok.mod = (await login('0900000003')).jar;
});
after(async () => { server.close(); await mongoose.disconnect(); await mongod.stop(); });

// ------------------------------------------------------------------ dùng chung
const MSG_LOGIN = 'Sai số điện thoại hoặc mật khẩu';
const otpOf = async (phone, purpose = 'register') => {
  const Otp = require('../src/modules/auth/otp.model');
  await Otp.updateOne({ phone, purpose }, { lastSentAt: new Date(Date.now() - 61000) });
  return (await api('POST', '/auth/otp/send', { body: { phone, purpose } })).body.data.devCode;
};
const registered = async (phone) => {
  const code = await otpOf(phone);
  await api('POST', '/auth/otp/verify', { body: { phone, purpose: 'register', code } });
  return api('POST', '/auth/register', { body: { name: 'Người dùng thử', phone, password: 'matkhau123' } });
};
const cheapFood = async (title = 'Cơm nhà') => (await api('GET', `/posts?q=${encodeURIComponent(title)}`)).body.data[0];
let addrId;
const buyer = async () => { if (!addrId) addrId = (await api('POST', '/me/addresses', { token: tok.thuy, body: { name: 'Ngọc Thủy', phone: '0901234567', block: 'B', unit: 'B-1204' } })).body.data._id; return addrId; };
const sellerPost = async (extra = {}) => (await api('POST', '/seller/posts', { token: tok.lan, body: {
  type: 'food', category: 'Đồ ăn', title: 'Bánh mì trứng nhà làm', description: 'Bánh mì nướng giòn, trứng ốp la, đồ ăn sáng.', price: 20000, unit: 'cái', area: 'B',
  fulfillmentModes: ['pickup'], payMethods: ['cash'], areas: ['Bcons'], priceType: 'fixed', ...extra } })).body.data;
const orderOf = async (post, extra = {}) => api('POST', '/orders', { token: tok.thuy, body: { postId: post._id, quantity: 1, fulfillment: 'pickup', payment: 'cash', ...extra } });
const phoBo = async () => (await api('GET', '/posts?limit=100')).body.data.find((p) => p.title.startsWith('Phở bò tái'));
const readyOrder = async () => { const o = (await orderOf(await phoBo())).body.data; for (const a of ['confirm', 'prepare', 'ready']) await act(tok.lan, o._id, a); return o; };
const doneOrder = async (extra = {}) => { const o = (await orderOf(await phoBo(), extra)).body.data; for (const a of ['confirm', 'prepare', 'ready']) await act(tok.lan, o._id, a); await api('POST', `/orders/${o._id}/confirm-received`, { token: tok.thuy }); return o; };

