tc(M1, 'TC_CL_AUTH_016', 'Mã OTP chỉ lưu dạng băm và chỉ dùng được một lần',
  { pre: 'Đã gửi mã OTP cho số 0911000008.', steps: ['Kiểm tra bản ghi mã trong cơ sở dữ liệu.', 'Xác minh mã đúng.', 'Xác minh lại cùng mã.'], input: 'Mã đúng do server sinh', expected: ['Cơ sở dữ liệu không chứa mã gốc, chỉ chứa bản băm.', 'Lần xác minh đầu: HTTP 200.', 'Lần hai: HTTP 409 (mã đã dùng).'] },
  async (c) => { const ph = '0911000008'; const code = await otpOf(ph); const row = await require('../src/modules/auth/otp.model').findOne({ phone: ph, purpose: 'register' }); c.ok('Không lưu mã gốc', row.codeHash && !row.codeHash.includes(code), 'chỉ có codeHash'); c.eq('Lần 1 → HTTP', (await api('POST', '/auth/otp/verify', { body: { phone: ph, purpose: 'register', code } })).status, 200); c.eq('Lần 2 → HTTP', (await api('POST', '/auth/otp/verify', { body: { phone: ph, purpose: 'register', code } })).status, 409); });
tc(M1, 'TC_CL_AUTH_017', 'Quên mật khẩu: đặt lại bằng OTP',
  { pre: 'Có tài khoản 0911000010 (mật khẩu cũ matkhau123).', steps: ['Chọn Quên mật khẩu, nhập số điện thoại.', 'Nhập mã OTP.', 'Nhập mật khẩu mới.', 'Đăng nhập lại.'], input: 'Số: 0911000010\nMật khẩu mới: MatKhauMoi@1', expected: ['Đặt lại thành công.', 'Đăng nhập bằng mật khẩu cũ bị từ chối (401).', 'Đăng nhập bằng mật khẩu mới thành công (200).'] },
  async (c) => { await registered('0911000010'); const code = await otpOf('0911000010', 'reset'); c.eq('Xác minh OTP reset → HTTP', (await api('POST', '/auth/otp/verify', { body: { phone: '0911000010', purpose: 'reset', code } })).status, 200); const rs = await api('POST', '/auth/password/reset', { body: { phone: '0911000010', password: 'MatKhauMoi@1' } }); c.ok('Đặt lại', [200, 204].includes(rs.status), `HTTP ${rs.status}`); c.eq('Mật khẩu cũ → HTTP', (await login('0911000010', 'matkhau123')).r.status, 401); c.eq('Mật khẩu mới → HTTP', (await login('0911000010', 'MatKhauMoi@1')).r.status, 200); });
tc(M1, 'TC_CL_AUTH_018', 'Đổi mật khẩu khi đã đăng nhập',
  { pre: 'Đã đăng nhập tài khoản 0911000010.', steps: ['Nhập sai mật khẩu hiện tại.', 'Nhập mật khẩu mới quá ngắn.', 'Nhập mật khẩu mới trùng mật khẩu cũ.', 'Nhập đúng mật khẩu hiện tại và mật khẩu mới hợp lệ.'], input: 'current / next lần lượt: (sai, hợp lệ), (đúng, "ngan"), (đúng, trùng cũ), (đúng, "Moi@2026ok")', expected: ['Ba trường hợp đầu bị từ chối (HTTP 422).', 'Trường hợp cuối thành công (HTTP 204); mật khẩu cũ hết dùng.'] },
  async (c) => { const { jar } = await login('0911000010', 'MatKhauMoi@1'); const p = (cur, nxt) => api('POST', '/auth/password/change', { token: jar, body: { current: cur, next: nxt } }); c.eq('Sai mật khẩu hiện tại → HTTP', (await p('Sai@2026x', 'Moi@2026ok')).status, 422); c.eq('Mật khẩu mới quá ngắn → HTTP', (await p('MatKhauMoi@1', 'ngan')).status, 422); c.eq('Trùng mật khẩu cũ → HTTP', (await p('MatKhauMoi@1', 'MatKhauMoi@1')).status, 422); c.eq('Hợp lệ → HTTP', (await p('MatKhauMoi@1', 'Moi@2026ok')).status, 204); c.eq('Mật khẩu cũ → HTTP', (await login('0911000010', 'MatKhauMoi@1')).r.status, 401); });
tc(M1, 'TC_CL_AUTH_019', 'Đăng xuất hủy phiên',
  { pre: 'Đã đăng nhập.', steps: ['Bấm Đăng xuất.', 'Mở lại hồ sơ của tôi.'], input: '—', expected: ['Đăng xuất thành công (HTTP 204).', 'Mở hồ sơ sau đó bị từ chối (HTTP 401).'] },
  async (c) => { const { jar } = await login('0900000005'); c.eq('Đăng xuất → HTTP', (await api('POST', '/auth/logout', { token: jar })).status, 204); c.eq('Hồ sơ sau đăng xuất → HTTP', (await api('GET', '/auth/profile', { token: jar })).status, 401); });

// ================================================================== 2. TÌM KIẾM, KHÁM PHÁ
const M2 = 'Client - Tìm kiếm & Khám phá';
tc(M2, 'TC_CL_SRCH_001', 'Danh sách bài đăng có phân trang',
  { pre: 'Có 8 bài mẫu đang mở.', steps: ['Mở trang chủ.', 'Yêu cầu danh sách bài, giới hạn 3 bài mỗi trang.'], input: 'limit = 3', expected: ['HTTP 200; trả đúng 3 bài.', 'Thông tin phân trang cho biết tổng số bài.'] },
  async (c) => { const r = await api('GET', '/posts?limit=3'); c.eq('HTTP', r.status, 200); c.eq('Số bài trả về', r.body.data.length, 3); c.eq('Tổng số bài', r.body.meta.total, 8); });
tc(M2, 'TC_CL_SRCH_002', 'Lọc bài theo loại',
  { pre: 'Có 3 bài đồ ăn, 3 bài đồ dùng, 2 bài dịch vụ.', steps: ['Chọn bộ lọc Đồ ăn.'], input: 'type = food', expected: ['Mọi bài trả về đều là loại đồ ăn.', 'Tổng số bằng 3.'] },
  async (c) => { const r = await api('GET', '/posts?type=food'); c.eq('Tổng số', r.body.meta.total, 3); c.ok('Mọi bài là đồ ăn', r.body.data.every((p) => p.type === 'food')); });
tc(M2, 'TC_CL_SRCH_003', 'Sắp xếp theo giá giảm dần',
  { pre: 'Có nhiều bài đồ ăn khác giá.', steps: ['Chọn sắp xếp Giá giảm dần.'], input: 'sort = -price', expected: ['Giá của bài đứng trước không nhỏ hơn bài đứng sau.'] },
  async (c) => { const r = await api('GET', '/posts?type=food&sort=-price'); const prices = r.body.data.map((p) => p.price); c.note(`Giá lần lượt: ${prices.join(', ')}`); c.ok('Giảm dần', prices.every((v, i) => i === 0 || prices[i - 1] >= v)); });
tc(M2, 'TC_CL_SRCH_004', 'Khoảng giá không hợp lệ',
  { pre: 'Đang ở trang tìm kiếm.', steps: ['Nhập giá tối thiểu lớn hơn giá tối đa.'], input: 'minPrice = 500, maxPrice = 100', expected: ['Bị từ chối (HTTP 422).'] },
  async (c) => c.eq('HTTP', (await api('GET', '/posts?minPrice=500&maxPrice=100')).status, 422));
tc(M2, 'TC_CL_SRCH_005', 'Tìm kiếm không dấu',
  { pre: 'Có bài "Cơm nhà làm, thực đơn đổi mỗi ngày".', steps: ['Gõ từ khóa không dấu vào ô tìm kiếm.'], input: 'q = "com nha lam"', expected: ['Kết quả đầu tiên là bài "Cơm nhà làm…".'] },
  async (c) => { const r = await api('GET', '/posts?q=' + encodeURIComponent('com nha lam')); c.note('Kết quả đầu: ' + (r.body.data[0] && r.body.data[0].title)); c.ok('Có bài Cơm nhà làm', r.body.data.length > 0 && r.body.data[0].title.startsWith('Cơm nhà')); });
tc(M2, 'TC_CL_SRCH_006', 'Tìm kiếm chịu gõ sai (lặp ký tự)',
  { pre: 'Có bài "Cơm nhà làm…".', steps: ['Gõ từ khóa bị lặp chữ.'], input: 'q = "coom nha lam"', expected: ['Bài "Cơm nhà làm…" vẫn nằm trong kết quả.'] },
  async (c) => { const r = await api('GET', '/posts?q=' + encodeURIComponent('coom nha lam')); const titles = r.body.data.map((p) => p.title); c.note('Kết quả: ' + titles.slice(0, 3).join(' | ')); c.ok('Có bài Cơm nhà làm', titles.some((t) => t.startsWith('Cơm nhà'))); });
tc(M2, 'TC_CL_SRCH_007', 'Từ khóa không liên quan trả về rỗng',
  { pre: 'Không có bài nào liên quan.', steps: ['Gõ từ khóa vô nghĩa.'], input: 'q = "xyzqwk"', expected: ['Danh sách rỗng, không trả bài không liên quan.'] },
  async (c) => { const r = await api('GET', '/posts?q=xyzqwk'); c.eq('Số bài', r.body.data.length, 0); });
tc(M2, 'TC_CL_SRCH_008', 'Xem chi tiết bài: id hợp lệ, sai định dạng, không tồn tại',
  { pre: 'Có bài đăng mẫu.', steps: ['Mở chi tiết một bài.', 'Mở với id sai định dạng.', 'Mở với id không tồn tại.'], input: 'id hợp lệ; "abc"; aaaaaaaaaaaaaaaaaaaaaaaa', expected: ['Id hợp lệ: HTTP 200 kèm người bán.', 'Id sai định dạng: HTTP 400.', 'Id không tồn tại: HTTP 404.'] },
  async (c) => { const p = (await api('GET', '/posts?limit=1')).body.data[0]; const r = await api('GET', `/posts/${p._id}`); c.eq('Hợp lệ → HTTP', r.status, 200); c.ok('Có người bán', !!r.body.data.seller && !!r.body.data.seller.name); c.eq('Sai định dạng → HTTP', (await api('GET', '/posts/abc')).status, 400); c.eq('Không tồn tại → HTTP', (await api('GET', '/posts/aaaaaaaaaaaaaaaaaaaaaaaa')).status, 404); });
tc(M2, 'TC_CL_SRCH_009', 'Địa chỉ chính xác của việc làm không hiện ở danh sách công khai',
  { pre: 'Có 5 việc làm mẫu.', steps: ['Mở danh sách việc làm khi chưa đăng nhập.'], input: '—', expected: ['Mỗi việc không có trường địa chỉ chính xác.'] },
  async (c) => { const r = await api('GET', '/jobs'); c.ok('Có việc làm', r.body.data.length >= 5); c.ok('Không lộ exactAddress', r.body.data.every((j) => j.exactAddress === undefined)); });
tc(M2, 'TC_CL_SRCH_010', 'Lưu bài và bỏ lưu',
  { pre: 'Đã đăng nhập 0900000001.', steps: ['Bấm tim lưu một bài hai lần.', 'Mở danh sách đã lưu và lọc theo loại việc làm.', 'Bỏ lưu.'], input: 'Một bài đồ ăn', expected: ['Lưu hai lần vẫn chỉ có một bài đã lưu.', 'Lọc theo việc làm cho danh sách rỗng.', 'Bỏ lưu xong danh sách trống.'] },
  async (c) => { const jar = (await login('0900000005')).jar; const food = (await api('GET', '/posts?type=food')).body.data[0]; await api('PUT', `/me/saved/${food._id}`, { token: jar }); await api('PUT', `/me/saved/${food._id}`, { token: jar }); c.eq('Số bài đã lưu', (await api('GET', '/me/saved', { token: jar })).body.data.length, 1); c.eq('Lọc việc làm', (await api('GET', '/me/saved?type=job', { token: jar })).body.data.length, 0); c.eq('Bỏ lưu → HTTP', (await api('DELETE', `/me/saved/${food._id}`, { token: jar })).status, 204); c.eq('Sau khi bỏ lưu', (await api('GET', '/me/saved', { token: jar })).body.data.length, 0); });
tc(M2, 'TC_CL_SRCH_011', 'Bài tương tự không chứa chính bài đang xem',
  { pre: 'Có nhiều bài đồ ăn.', steps: ['Mở chi tiết bài, xem mục Tương tự trong khu.'], input: 'Bài "Cơm nhà làm…"', expected: ['HTTP 200; danh sách không chứa chính bài đang xem.'] },
  async (c) => { const p = await cheapFood(); const r = await api('GET', `/posts/${p._id}/similar`); c.eq('HTTP', r.status, 200); c.ok('Không chứa chính nó', !r.body.data.some((x) => x._id === p._id), `${r.body.data.length} bài tương tự`); });
tc(M2, 'TC_CL_SRCH_012', 'Giờ vàng: tham số thời gian sai bị từ chối',
  { pre: 'Server đang chạy.', steps: ['Gọi danh sách bài đang giảm giá với tham số now hợp lệ.', 'Gọi với now sai.'], input: 'now = 2026-11-17T12:00:00+07:00; now = abc', expected: ['Hợp lệ: HTTP 200.', 'Sai: HTTP 422.'] },
  async (c) => { c.eq('Hợp lệ → HTTP', (await api('GET', '/deals?now=' + encodeURIComponent('2026-11-17T12:00:00+07:00'))).status, 200); c.eq('Sai → HTTP', (await api('GET', '/deals?now=abc')).status, 422); });

// ================================================================== 3. ĐẶT HÀNG
const M3 = 'Client - Đặt hàng';
tc(M3, 'TC_CL_ORD_001', 'Đặt đơn đồ ăn giao tận nơi: server tự tính tiền',
  { pre: 'Đã đăng nhập; có địa chỉ nhận hàng; bài "Cơm nhà làm" giá 35.000đ, phí giao 7.000đ, món Sườn rim +10.000đ, thêm Trứng +5.000đ.', steps: ['Mở bài, chọn Sườn rim và Trứng, số lượng 2.', 'Chọn giao tận nơi, tiền mặt.', 'Bấm Đặt đơn.'], input: 'quantity = 2; total do trình duyệt gửi = 1 (cố tình sai)', expected: ['Đơn được tạo (HTTP 201), mã dạng AG-O….', 'Tổng tiền = (35.000 + 10.000 + 5.000) × 2 + 7.000 = 107.000đ; giá trị total do trình duyệt gửi bị bỏ qua.', 'Đơn lưu bản chụp tên bài.'] },
  async (c) => { const post = await cheapFood(); const r = await api('POST', '/orders', { token: tok.thuy, body: { postId: post._id, quantity: 2, fulfillment: 'delivery', addressId: await buyer(), payment: 'cash', total: 1, selections: [{ group: 'Món mặn', choices: ['Sườn rim'] }, { group: 'Thêm', choices: ['Trứng'] }] } }); c.eq('HTTP', r.status, 201); c.eq('Tổng tiền', money(r.body.data.total), money(107000)); c.ok('Mã đơn', /^AG-O\d+$/.test(r.body.data.code), r.body.data.code); c.eq('Bản chụp tên bài', r.body.data.snapshot.title, post.title); });
tc(M3, 'TC_CL_ORD_002', 'Đặt đơn thiếu nhóm tùy chọn bắt buộc và thiếu địa chỉ',
  { pre: 'Đã đăng nhập; bài "Cơm nhà làm" có nhóm Món mặn bắt buộc.', steps: ['Chọn giao tận nơi nhưng không chọn món mặn và không chọn địa chỉ.', 'Bấm Đặt đơn.'], input: 'selections = []; không có addressId', expected: ['Bị từ chối (HTTP 422) kèm lý do thiếu món mặn và thiếu địa chỉ.', 'Không tạo đơn.'] },
  async (c) => { const post = await cheapFood(); const before = (await api('GET', '/orders', { token: tok.thuy })).body.meta.total; const r = await api('POST', '/orders', { token: tok.thuy, body: { postId: post._id, quantity: 1, fulfillment: 'delivery', payment: 'cash', selections: [] } }); c.eq('HTTP', r.status, 422); c.eq('Số đơn không đổi', (await api('GET', '/orders', { token: tok.thuy })).body.meta.total, before); });
tc(M3, 'TC_CL_ORD_003', 'Đặt tự lấy: không cần địa chỉ và không tính phí giao',
  { pre: 'Đã đăng nhập; bài Phở bò tái cho tự lấy.', steps: ['Chọn Tự lấy, tiền mặt.', 'Bấm Đặt đơn.'], input: 'fulfillment = pickup', expected: ['Đơn tạo thành công (HTTP 201).', 'Tổng tiền bằng giá bài, không có phí giao.'] },
  async (c) => { const p = await phoBo(); const r = await orderOf(p); c.eq('HTTP', r.status, 201); c.eq('Tổng tiền', money(r.body.data.total), money(p.price)); });
tc(M3, 'TC_CL_ORD_004', 'Số lượng không hợp lệ',
  { pre: 'Đã đăng nhập.', steps: ['Gửi đơn với số lượng 0.', 'Gửi đơn với số lượng âm.'], input: 'quantity = 0; quantity = -3', expected: ['Cả hai bị từ chối (HTTP 422).'] },
  async (c) => { const p = await phoBo(); c.eq('Số lượng 0 → HTTP', (await orderOf(p, { quantity: 0 })).status, 422); c.eq('Số lượng âm → HTTP', (await orderOf(p, { quantity: -3 })).status, 422); });
tc(M3, 'TC_CL_ORD_005', 'Bài bán một lần: người mua thứ hai bị từ chối',
  { pre: 'Bài tai nghe cũ thuộc loại bán một lần.', steps: ['Người mua thứ nhất đặt thành công.', 'Người mua thứ hai đặt cùng bài.'], input: 'stock.mode = once', expected: ['Lần 1: HTTP 201.', 'Lần 2: HTTP 409 vì bài đã hết.'] },
  async (c) => { const p = (await api('GET', '/posts?q=Tai nghe')).body.data[0]; c.eq('Lần 1 → HTTP', (await orderOf(p)).status, 201); const r2 = await api('POST', '/orders', { token: tok.quoc, body: { postId: p._id, quantity: 1, fulfillment: 'pickup', payment: 'cash' } }); c.eq('Lần 2 → HTTP', r2.status, 409); });
tc(M3, 'TC_CL_ORD_006', 'Đặt vượt số lượng còn lại thì không trừ kho',
  { pre: 'Bài giới hạn còn 2 phần.', steps: ['Đặt 3 phần.', 'Kiểm tra số còn lại.'], input: 'stock.left = 2; quantity = 3', expected: ['Bị từ chối (HTTP 409).', 'Số còn lại vẫn là 2.'] },
  async (c) => { const p = await sellerPost({ title: 'Xôi lá chuối', stock: { mode: 'limit', left: 2 } }); const r = await orderOf(p, { quantity: 3 }); c.eq('HTTP', r.status, 409); const left = (await api('GET', '/seller/posts', { token: tok.lan })).body.data.find((x) => x._id === p._id).stock.left; c.eq('Số còn lại', left, 2); });
tc(M3, 'TC_CL_ORD_007', 'Dịch vụ cần lịch hẹn: thiếu hoặc chọn giờ trong quá khứ',
  { pre: 'Bài "Dọn nhà theo giờ" yêu cầu chọn ngày giờ.', steps: ['Đặt mà không chọn ngày giờ.', 'Đặt với giờ đã qua.'], input: 'scheduledAt: (trống); 2020-01-01T08:00', expected: ['Cả hai bị từ chối (HTTP 422) với thông báo về ngày giờ.'] },
  async (c) => { const p = (await api('GET', '/posts?q=Dọn nhà')).body.data[0]; const a = await api('POST', '/orders', { token: tok.thuy, body: { postId: p._id, quantity: 1, fulfillment: 'delivery', addressId: await buyer(), payment: 'cash' } }); c.eq('Thiếu lịch → HTTP', a.status, 422); c.ok('Nhắc ngày giờ', JSON.stringify(a.body).includes('scheduledAt')); const b = await api('POST', '/orders', { token: tok.thuy, body: { postId: p._id, quantity: 1, fulfillment: 'delivery', addressId: await buyer(), payment: 'cash', scheduledAt: '2020-01-01T08:00:00+07:00' } }); c.eq('Giờ quá khứ → HTTP', b.status, 422); });
tc(M3, 'TC_CL_ORD_008', 'Đặt đơn khi chưa đăng nhập',
  { pre: 'Chưa đăng nhập.', steps: ['Gửi yêu cầu đặt đơn không kèm phiên đăng nhập.'], input: '—', expected: ['Bị từ chối (HTTP 401).'] },
  async (c) => { const p = await phoBo(); c.eq('HTTP', (await api('POST', '/orders', { body: { postId: p._id, quantity: 1, fulfillment: 'pickup', payment: 'cash' } })).status, 401); });
tc(M3, 'TC_CL_ORD_009', 'Voucher không tồn tại hoặc không đủ điều kiện',
  { pre: 'Đã đăng nhập; chưa đổi voucher nào.', steps: ['Nhập mã voucher không có.', 'Bấm Đặt đơn.'], input: 'voucherCode = "KHONGCO"', expected: ['Bị từ chối (mã lỗi 4xx), không tạo đơn.'] },
  async (c) => { const p = await phoBo(); const r = await orderOf(p, { voucherCode: 'KHONGCO' }); c.ok('Bị từ chối', r.status >= 400 && r.status < 500, `HTTP ${r.status}`); });
tc(M3, 'TC_CL_ORD_010', 'Giỏ nháp của khách được giữ khi đăng nhập và thanh toán đúng tổng',
  { pre: 'Khách chưa đăng nhập.', steps: ['Thêm một món vào giỏ khi chưa đăng nhập.', 'Đăng nhập.', 'Thanh toán giỏ.'], input: 'Một bài đồ ăn, số lượng 1', expected: ['Món vẫn còn trong giỏ sau khi đăng nhập.', 'Thanh toán tạo đơn đúng chủ và đúng tổng tiền.'] },
  async (c) => { const jar = newJar(); const p = await phoBo(); const add = await api('POST', '/cart', { token: jar, body: { postId: p._id, quantity: 1 } }); c.ok('Thêm vào giỏ', [200, 201].includes(add.status), `HTTP ${add.status}`); await api('POST', '/auth/login', { body: { phone: '0900000005', password: PW }, token: jar }); const cart = (await api('GET', '/cart', { token: jar })).body.data; c.ok('Giỏ còn món sau khi đăng nhập', JSON.stringify(cart).includes(p._id)); const co = await api('POST', '/cart/checkout', { token: jar, body: { fulfillment: 'pickup', payment: 'cash' } }); c.ok('Thanh toán giỏ', [200, 201].includes(co.status), `HTTP ${co.status}`); });

// ================================================================== 4. THEO DÕI ĐƠN, HẬU MÃI
const M4 = 'Client - Theo dõi đơn & Hậu mãi';
tc(M4, 'TC_CL_TRK_001', 'Chỉ người liên quan mới xem được đơn',
  { pre: 'Có đơn của Ngọc Thủy gửi Bếp Cô Lan.', steps: ['Người mua mở đơn.', 'Người bán mở đơn.', 'Người dùng khác mở đơn.'], input: '—', expected: ['Người mua: HTTP 200.', 'Người ngoài: HTTP 403.'] },
  async (c) => { const o = (await orderOf(await phoBo())).body.data; c.eq('Người mua → HTTP', (await api('GET', `/orders/${o._id}`, { token: tok.thuy })).status, 200); c.eq('Người ngoài → HTTP', (await api('GET', `/orders/${o._id}`, { token: tok.hoa })).status, 403); });
tc(M4, 'TC_CL_TRK_002', 'Danh sách đơn lọc theo trạng thái đang diễn ra',
  { pre: 'Người mua có đơn đang diễn ra.', steps: ['Mở Đơn hàng, chọn đang diễn ra.'], input: 'state = active', expected: ['HTTP 200; tổng số đơn bằng số đơn chưa kết thúc.'] },
  async (c) => { const r = await api('GET', '/orders?state=active', { token: tok.thuy }); c.eq('HTTP', r.status, 200); c.ok('Có đơn đang diễn ra', r.body.meta.total >= 1, `tổng ${r.body.meta.total}`); c.ok('Không có đơn đã xong', r.body.data.every((o) => !['done', 'cancelled', 'declined'].includes(o.state))); });
tc(M4, 'TC_CL_TRK_003', 'Theo dõi đơn giao tận nơi chỉ dành cho chủ đơn và người bán',
  { pre: 'Có một đơn giao tận nơi và một đơn tự lấy.', steps: ['Chủ đơn xem tiến trình giao.', 'Người ngoài xem.', 'Xem đơn tự lấy.'], input: '—', expected: ['Chủ đơn và người bán: HTTP 200.', 'Người ngoài: HTTP 403.', 'Đơn tự lấy: HTTP 404 NO_TRACKING.'] },
  async (c) => { const p = await cheapFood(); const d = (await api('POST', '/orders', { token: tok.thuy, body: { postId: p._id, quantity: 1, fulfillment: 'delivery', addressId: await buyer(), payment: 'cash', selections: [{ group: 'Món mặn', choices: ['Gà kho gừng'] }] } })).body.data; c.eq('Chủ đơn → HTTP', (await api('GET', `/orders/${d._id}/tracking`, { token: tok.thuy })).status, 200); c.eq('Người bán → HTTP', (await api('GET', `/orders/${d._id}/tracking`, { token: tok.lan })).status, 200); c.eq('Người ngoài → HTTP', (await api('GET', `/orders/${d._id}/tracking`, { token: tok.quoc })).status, 403); const pk = (await orderOf(await phoBo())).body.data; const r = await api('GET', `/orders/${pk._id}/tracking`, { token: tok.thuy }); c.eq('Đơn tự lấy → HTTP', r.status, 404); c.eq('Mã lỗi', r.body.error.code, 'NO_TRACKING'); });
tc(M4, 'TC_CL_TRK_004', 'Hủy ngay khi người bán chưa bắt đầu',
  { pre: 'Đơn đang Chờ xác nhận.', steps: ['Bấm Hủy đơn, không nhập lý do.', 'Nhập lý do và hủy.', 'Hủy lần nữa.'], input: 'reason: (trống); "Đặt nhầm món"', expected: ['Không có lý do: HTTP 422.', 'Có lý do: đơn Đã hủy, ghi bên hủy là người mua.', 'Hủy lần hai: HTTP 409.'] },
  async (c) => { const o = (await orderOf(await phoBo())).body.data; c.eq('Không lý do → HTTP', (await api('POST', `/orders/${o._id}/cancel`, { token: tok.thuy, body: {} })).status, 422); const r = await api('POST', `/orders/${o._id}/cancel`, { token: tok.thuy, body: { reason: 'Đặt nhầm món' } }); c.eq('Trạng thái', r.body.data.state, 'cancelled'); c.eq('Bên hủy', r.body.data.cancelInfo.by, 'buyer'); c.eq('Hủy lần hai → HTTP', (await api('POST', `/orders/${o._id}/cancel`, { token: tok.thuy, body: { reason: 'Hủy lần nữa' } })).status, 409); });
tc(M4, 'TC_CL_TRK_005', 'Đơn đã chuẩn bị chỉ xin hủy chứ không hủy ngay',
  { pre: 'Người bán đã xác nhận và bắt đầu chuẩn bị.', steps: ['Bấm Hủy đơn.', 'Gửi yêu cầu hủy.', 'Gửi yêu cầu hủy lần hai.'], input: 'reason = "Có việc đột xuất"', expected: ['Hủy ngay: HTTP 409.', 'Yêu cầu hủy: HTTP 200.', 'Yêu cầu lần hai: HTTP 409.'] },
  async (c) => { const o = (await orderOf(await phoBo())).body.data; await act(tok.lan, o._id, 'confirm'); await act(tok.lan, o._id, 'prepare'); c.eq('Hủy ngay → HTTP', (await api('POST', `/orders/${o._id}/cancel`, { token: tok.thuy, body: { reason: 'Muốn hủy' } })).status, 409); c.eq('Xin hủy → HTTP', (await api('POST', `/orders/${o._id}/cancel-request`, { token: tok.thuy, body: { reason: 'Có việc đột xuất' } })).status, 200); c.eq('Xin hủy lần hai → HTTP', (await api('POST', `/orders/${o._id}/cancel-request`, { token: tok.thuy, body: { reason: 'Có việc đột xuất' } })).status, 409); });
tc(M4, 'TC_CL_TRK_006', 'Xác nhận đã nhận hàng',
  { pre: 'Đơn đang ở bước Sẵn sàng.', steps: ['Xác nhận nhận hàng khi đơn chưa tới bước nhận.', 'Người khác xác nhận.', 'Chủ đơn xác nhận.', 'Chủ đơn xác nhận lần hai.'], input: '—', expected: ['Chưa tới bước: HTTP 409.', 'Người ngoài: HTTP 403.', 'Chủ đơn: đơn Hoàn thành.', 'Lần hai: HTTP 409.'] },
  async (c) => { const o = (await orderOf(await phoBo())).body.data; c.eq('Chưa tới bước → HTTP', (await api('POST', `/orders/${o._id}/confirm-received`, { token: tok.thuy })).status, 409); for (const a of ['confirm', 'prepare', 'ready']) await act(tok.lan, o._id, a); c.eq('Người ngoài → HTTP', (await api('POST', `/orders/${o._id}/confirm-received`, { token: tok.quoc })).status, 403); c.eq('Chủ đơn → trạng thái', (await api('POST', `/orders/${o._id}/confirm-received`, { token: tok.thuy })).body.data.state, 'done'); c.eq('Lần hai → HTTP', (await api('POST', `/orders/${o._id}/confirm-received`, { token: tok.thuy })).status, 409); });
tc(M4, 'TC_CL_TRK_007', 'Báo vấn đề với đơn đồ ăn: bắt buộc ảnh, chỉ một yêu cầu',
  { pre: 'Đơn đồ ăn vừa hoàn thành (trong 2 giờ).', steps: ['Báo vấn đề không kèm ảnh.', 'Báo vấn đề kèm ảnh.', 'Báo vấn đề lần hai.'], input: 'type = "Món bị nguội"; photos = 0 rồi 1', expected: ['Không ảnh: HTTP 422.', 'Có ảnh: HTTP 201, trạng thái yêu cầu là mở.', 'Lần hai: HTTP 409.'] },
  async (c) => { const o = await doneOrder(); c.eq('Không ảnh → HTTP', (await api('POST', `/orders/${o._id}/issue`, { token: tok.thuy, body: { type: 'Món bị nguội', photos: 0 } })).status, 422); const r = await api('POST', `/orders/${o._id}/issue`, { token: tok.thuy, body: { type: 'Món bị nguội', text: 'Giao tới đã nguội ngắt', photos: 1 } }); c.eq('Có ảnh → HTTP', r.status, 201); c.eq('Trạng thái yêu cầu', r.body.data.issue.st, 'open'); c.eq('Lần hai → HTTP', (await api('POST', `/orders/${o._id}/issue`, { token: tok.thuy, body: { type: 'Lần hai', photos: 1 } })).status, 409); });
tc(M4, 'TC_CL_TRK_008', 'Người bán hoàn tiền cho báo vấn đề',
  { pre: 'Đơn hoàn thành có báo vấn đề.', steps: ['Người bán hoàn quá tổng đơn.', 'Hoàn 20.000đ kèm lời giải thích.', 'Người mua đóng báo vấn đề.'], input: 'amount = 999999; amount = 20000', expected: ['Quá tổng: HTTP 422.', 'Hợp lệ: trạng thái hoàn tiền, số tiền 20.000đ.', 'Người mua đóng xong thấy "đã nhận tiền hoàn 20.000đ".'] },
  async (c) => { const o = await doneOrder(); await api('POST', `/orders/${o._id}/issue`, { token: tok.thuy, body: { type: 'Thiếu món', photos: 2 } }); c.eq('Hoàn quá tổng → HTTP', (await act(tok.lan, o._id, 'issueRefund', { amount: 999999 })).status, 422); const r = await act(tok.lan, o._id, 'issueRefund', { amount: 20000, reply: 'Xin lỗi bạn, mình hoàn 20.000đ' }); c.eq('Trạng thái', r.body.data.issue.st, 'refund'); const cl = await api('POST', `/orders/${o._id}/issue/close`, { token: tok.thuy, body: {} }); c.ok('Kết quả ghi nhận', /đã nhận tiền hoàn 20\.000đ/.test(cl.body.data.issue.result), cl.body.data.issue.result); });
tc(M4, 'TC_CL_TRK_009', 'Báo vấn đề quá 2 giờ sau khi xong đơn đồ ăn',
  { pre: 'Đơn đồ ăn đã hoàn thành cách đây 3 giờ.', steps: ['Báo vấn đề kèm ảnh.'], input: 'photos = 1', expected: ['Bị từ chối (HTTP 409) vì quá thời hạn 2 giờ.'] },
  async (c) => { const o = await doneOrder(); await mongoose.model('Order').collection.updateOne({ _id: new mongoose.Types.ObjectId(o._id) }, { $set: { 'history.$[h].at': new Date(Date.now() - 3 * 3600 * 1000) } }, { arrayFilters: [{ 'h.state': 'done' }] }); c.eq('HTTP', (await api('POST', `/orders/${o._id}/issue`, { token: tok.thuy, body: { type: 'Muộn rồi', photos: 1 } })).status, 409); });
tc(M4, 'TC_CL_TRK_010', 'Đánh giá đơn đã hoàn thành',
  { pre: 'Có một đơn đã hoàn thành và một đơn chưa xong.', steps: ['Đánh giá đơn chưa xong.', 'Đánh giá 6 sao.', 'Người lạ đánh giá.', 'Đánh giá 4 sao kèm nhận xét.', 'Đánh giá lần hai.'], input: 'rating = 6; rating = 4, comment = "Ngon"', expected: ['Chưa xong: HTTP 409.', '6 sao: HTTP 422.', 'Người lạ: HTTP 403.', 'Hợp lệ: HTTP 201.', 'Lần hai: HTTP 409.'] },
  async (c) => { const open = (await orderOf(await phoBo())).body.data; c.eq('Đơn chưa xong → HTTP', (await api('POST', '/reviews', { token: tok.thuy, body: { targetType: 'order', targetId: open._id, rating: 5 } })).status, 409); const o = await doneOrder(); c.eq('6 sao → HTTP', (await api('POST', '/reviews', { token: tok.thuy, body: { targetType: 'order', targetId: o._id, rating: 6 } })).status, 422); c.eq('Người lạ → HTTP', (await api('POST', '/reviews', { token: tok.hoa, body: { targetType: 'order', targetId: o._id, rating: 5 } })).status, 403); c.eq('Hợp lệ → HTTP', (await api('POST', '/reviews', { token: tok.thuy, body: { targetType: 'order', targetId: o._id, rating: 4, comment: 'Ngon' } })).status, 201); c.eq('Lần hai → HTTP', (await api('POST', '/reviews', { token: tok.thuy, body: { targetType: 'order', targetId: o._id, rating: 5 } })).status, 409); });
tc(M4, 'TC_CL_TRK_011', 'Đơn chờ xác nhận quá hạn tự hủy',
  { pre: 'Đơn đồ ăn đã chờ người bán 20 phút (hạn 10 phút).', steps: ['Người mua mở lại đơn.', 'Người bán xem danh sách đơn.'], input: 'createdAt lùi 20 phút', expected: ['Đơn chuyển sang Đã hủy, bên hủy là hệ thống.', 'Người bán thấy cùng kết quả.'] },
  async (c) => { const o = (await orderOf(await phoBo())).body.data; await mongoose.model('Order').collection.updateOne({ _id: new mongoose.Types.ObjectId(o._id) }, { $set: { createdAt: new Date(Date.now() - 20 * 60 * 1000) } }); const seen = (await api('GET', `/orders/${o._id}`, { token: tok.thuy })).body.data; c.eq('Trạng thái', seen.state, 'cancelled'); c.eq('Bên hủy', seen.cancelInfo.by, 'system'); c.eq('Người bán thấy', (await api('GET', '/seller/orders', { token: tok.lan })).body.data.find((x) => x._id === o._id).state, 'cancelled'); });
const laundry = async () => { const post = (await api('GET', '/posts?limit=100')).body.data.find((p) => p.title.startsWith('Giặt sấy gấp')); const placed = (await api('POST', '/orders', { token: tok.thuy, body: { postId: post._id, quantity: 3, fulfillment: 'delivery', addressId: await buyer(), payment: 'cash', scheduledAt: new Date(Date.now() + 86400000).toISOString(), answers: [{ question: 'Khối lượng ước tính (kg)', value: '4' }] } })).body.data; return placed; };
const quoted = async () => { const o = await laundry(); await act(tok.linh, o._id, 'confirm'); await act(tok.linh, o._id, 'pickUp'); const q = await act(tok.linh, o._id, 'quote', { lines: [{ name: 'Giặt sấy 4,5 kg', qty: 4.5, price: 18000 }, { name: 'Giặt chăn', qty: 1, price: 40000 }] }); return { o, q }; };
tc(M4, 'TC_CL_TRK_012', 'Đơn giặt sấy: người bán báo giá, người mua đồng ý',
  { pre: 'Đơn giặt sấy 3 kg đã được người bán xác nhận và đã lấy đồ.', steps: ['Người bán nhập báo giá hai dòng.', 'Người khác thử duyệt giúp.', 'Người mua đồng ý báo giá.', 'Người bán trả đồ.'], input: 'Dòng 1: giặt sấy 4,5 kg × 18.000đ; dòng 2: giặt chăn 1 × 40.000đ', expected: ['Đơn sang Chờ duyệt giá, tổng báo giá 121.000đ.', 'Người ngoài duyệt: HTTP 403.', 'Sau khi đồng ý: tổng đơn = giá cuối + phí giao, trạng thái Đang xử lý.', 'Trả đồ xong: đơn Hoàn thành.'] },
  async (c) => { const { o, q } = await quoted(); c.eq('Loại đơn', o.flow, 'laundry'); c.eq('Trạng thái sau báo giá', q.body.data.state, 'pricing'); c.eq('Tổng báo giá', q.body.data.quote.total, 121000); c.eq('Người ngoài duyệt → HTTP', (await api('POST', `/orders/${o._id}/approve-quote`, { token: tok.hoa })).status, 403); const ok = (await api('POST', `/orders/${o._id}/approve-quote`, { token: tok.thuy })).body.data; c.eq('Sau khi đồng ý', ok.total, 121000 + (o.breakdown.deliveryFee || 0)); c.eq('Trạng thái', ok.state, 'preparing'); c.eq('Trả đồ → trạng thái', (await act(tok.linh, o._id, 'returned')).body.data.state, 'done'); });
tc(M4, 'TC_CL_TRK_013', 'Đơn giặt sấy: người mua từ chối báo giá',
  { pre: 'Đơn giặt sấy đã có báo giá chờ duyệt.', steps: ['Người mua từ chối báo giá.'], input: 'Báo giá 121.000đ', expected: ['Đơn chuyển sang Đã hủy.', 'Tổng tiền ban đầu được giữ nguyên.'] },
  async (c) => { const { o } = await quoted(); const r = await api('POST', `/orders/${o._id}/reject-quote`, { token: tok.thuy, body: {} }); c.eq('Trạng thái', r.body.data.state, 'cancelled'); c.eq('Tổng tiền giữ nguyên', r.body.data.total, o.total); });

// ================================================================== 5. NHẬN VIỆC
const M5 = 'Client - Nhận việc';
const job = async (prefix) => (await api('GET', '/jobs')).body.data.find((j) => j.title.startsWith(prefix));
tc(M5, 'TC_CL_JOB_001', 'Hỏi đáp công khai chặn số điện thoại',
  { pre: 'Việc "Lấy giúp phần cơm" đang mở; đã đăng nhập.', steps: ['Gửi câu hỏi có chứa số điện thoại.', 'Gửi câu hỏi bình thường.'], input: '"Gọi mình 0901 234 567 nhé"; "Cổng sau có bảo vệ không?"', expected: ['Câu có số điện thoại bị từ chối (HTTP 422).', 'Câu bình thường: HTTP 201 và hiện công khai.'] },
  async (c) => { const j = await job('Lấy giúp'); c.eq('Chứa SĐT → HTTP', (await api('POST', `/jobs/${j._id}/questions`, { token: tok.thuy, body: { text: 'Gọi mình 0901 234 567 nhé' } })).status, 422); c.eq('Bình thường → HTTP', (await api('POST', `/jobs/${j._id}/questions`, { token: tok.thuy, body: { text: 'Cổng sau có bảo vệ không?' } })).status, 201); c.ok('Hiện công khai', (await api('GET', `/jobs/${j._id}/questions`)).body.data.length >= 1); });
tc(M5, 'TC_CL_JOB_002', 'Không thể tự nhận việc của chính mình và lời giới thiệu quá ngắn',
  { pre: 'Việc do Chị Hoa đăng.', steps: ['Chị Hoa gửi đề nghị cho việc của mình.', 'Người khác gửi đề nghị với lời giới thiệu 2 ký tự.'], input: 'intro = "Tự nhận việc mình"; intro = "ab"', expected: ['Người đăng tự nhận: HTTP 403.', 'Lời giới thiệu quá ngắn: HTTP 422.'] },
  async (c) => { const j = await job('Lấy giúp'); c.eq('Tự nhận → HTTP', (await api('POST', `/jobs/${j._id}/offers`, { token: tok.hoa, body: { intro: 'Tự nhận việc mình' } })).status, 403); c.eq('Quá ngắn → HTTP', (await api('POST', `/jobs/${j._id}/offers`, { token: tok.thuy, body: { intro: 'ab' } })).status, 422); });
tc(M5, 'TC_CL_JOB_003', 'Gửi đề nghị nhận việc, không lộ địa chỉ chính xác, không gửi trùng',
  { pre: 'Việc "Dọn phòng cuối tuần" do Quốc Anh đăng đang mở.', steps: ['Gửi đề nghị kèm lời giới thiệu.', 'Xem chi tiết việc.', 'Gửi đề nghị lần hai.'], input: 'intro = "Mình ở cùng block, rảnh sáng mai."', expected: ['HTTP 201, trạng thái Đã gửi đề nghị.', 'Chưa có địa chỉ chính xác.', 'Lần hai: HTTP 409.'] },
  async (c) => { const j = await job('Dọn phòng'); const r = await api('POST', `/jobs/${j._id}/offers`, { token: tok.thuy, body: { intro: 'Mình ở cùng block, rảnh sáng mai.' } }); c.eq('HTTP', r.status, 201); c.eq('Trạng thái', r.body.data.state, 'offered'); c.eq('Địa chỉ chính xác', r.body.data.job.exactAddress, undefined); c.eq('Gửi lần hai → HTTP', (await api('POST', `/jobs/${j._id}/offers`, { token: tok.thuy, body: { intro: 'Gửi lần hai nè' } })).status, 409); });
tc(M5, 'TC_CL_JOB_004', 'Không nhảy bước trạng thái khi chưa được chọn',
  { pre: 'Đề nghị đang ở trạng thái Đã gửi đề nghị.', steps: ['Bấm Bắt đầu làm.', 'Bấm Xác nhận đã nhận tiền công.', 'Người khác xem đề nghị.'], input: '—', expected: ['Cả hai bước bị từ chối (HTTP 409).', 'Người ngoài xem: HTTP 403.'] },
  async (c) => { const j = await job('Cho mèo'); const o = (await api('POST', `/jobs/${j._id}/offers`, { token: tok.quoc, body: { intro: 'Mình yêu mèo lắm, nuôi hai bé.' } })).body.data; c.eq('Bắt đầu → HTTP', (await api('POST', `/offers/${o._id}/start`, { token: tok.quoc })).status, 409); c.eq('Xác nhận đã nhận tiền → HTTP', (await api('POST', `/offers/${o._id}/confirm-paid`, { token: tok.quoc })).status, 409); c.eq('Người ngoài xem → HTTP', (await api('GET', `/offers/${o._id}`, { token: tok.may })).status, 403); });
tc(M5, 'TC_CL_JOB_005', 'Sửa lời giới thiệu và rút đề nghị',
  { pre: 'Đề nghị đang chờ chọn.', steps: ['Sửa lời giới thiệu.', 'Rút đề nghị.', 'Gửi lại đề nghị.'], input: 'intro mới: "Đã sửa lời giới thiệu"', expected: ['Sửa: HTTP 200.', 'Rút: trạng thái Đã rút, số đề nghị của việc giảm.', 'Gửi lại được: HTTP 201.'] },
  async (c) => { const j = await job('Kèm Toán'); const o = (await api('POST', `/jobs/${j._id}/offers`, { token: tok.thuy, body: { intro: 'Mình dạy được hình học lớp 8.' } })).body.data; c.eq('Sửa → HTTP', (await api('PATCH', `/offers/${o._id}`, { token: tok.thuy, body: { intro: 'Đã sửa lời giới thiệu' } })).status, 200); c.eq('Rút → trạng thái', (await api('POST', `/offers/${o._id}/withdraw`, { token: tok.thuy })).body.data.state, 'withdrawn'); c.eq('Gửi lại → HTTP', (await api('POST', `/jobs/${j._id}/offers`, { token: tok.thuy, body: { intro: 'Mình dạy được hình học lớp 8.' } })).status, 201); });
tc(M5, 'TC_CL_JOB_006', 'Được chọn thì thấy địa chỉ chính xác, người khác không gửi thêm được',
  { pre: 'Việc "Chuyển 2 thùng đồ" do Quốc Anh đăng, đã có một đề nghị.', steps: ['Người đăng chọn người làm.', 'Người làm xem chi tiết việc.', 'Người khác hỏi hoặc gửi đề nghị.'], input: '—', expected: ['Đề nghị chuyển sang Được chọn.', 'Người được chọn thấy địa chỉ chính xác.', 'Người khác bị từ chối (HTTP 409) vì việc đã đủ người.'] },
  async (c) => { const j = await job('Chuyển 2 thùng'); const o = (await api('POST', `/jobs/${j._id}/offers`, { token: tok.thuy, body: { intro: 'Mình có sức, chuyển nhanh gọn.' } })).body.data; const ch = await api('POST', `/seller/offers/${o._id}/choose`, { token: tok.quoc }); c.eq('Người đăng chọn → HTTP', ch.status, 200); const mine = (await api('GET', `/offers/${o._id}`, { token: tok.thuy })).body.data; c.eq('Trạng thái', mine.state, 'chosen'); c.ok('Thấy địa chỉ chính xác', !!mine.job.exactAddress); c.eq('Người khác gửi đề nghị → HTTP', (await api('POST', `/jobs/${j._id}/offers`, { token: tok.hoa, body: { intro: 'Mình cũng muốn làm' } })).status, 409); });
tc(M5, 'TC_CL_JOB_007', 'Bắt đầu, báo hoàn thành (ghi chú bắt buộc) và xác nhận nhận tiền công',
  { pre: 'Đề nghị đã được chọn.', steps: ['Bấm Bắt đầu làm.', 'Báo hoàn thành với ghi chú trống.', 'Báo hoàn thành kèm ghi chú.', 'Người đăng xác nhận hoàn thành.', 'Người làm xác nhận nhận tiền, rồi đánh giá.'], input: 'note = ""; note = "Đã mang cơm lên"', expected: ['Đang làm.', 'Ghi chú trống: HTTP 422.', 'Đã báo xong.', 'Hoàn thành.', 'Nhận tiền: HTTP 200; xác nhận lần hai: HTTP 409; đánh giá: HTTP 201.'] },
  async (c) => { const j = await job('Lấy giúp'); const o = (await api('POST', `/jobs/${j._id}/offers`, { token: tok.may, body: { intro: 'Mình ở gần cổng sau, lấy giúp được.' } })).body.data; await api('POST', `/dev/jobs/${j._id}/offers/${o._id}/choose`, { token: tok.hoa }); c.eq('Bắt đầu → trạng thái', (await api('POST', `/offers/${o._id}/start`, { token: tok.may })).body.data.state, 'working'); c.eq('Ghi chú trống → HTTP', (await api('POST', `/offers/${o._id}/report-done`, { token: tok.may, body: { note: '' } })).status, 422); c.eq('Báo xong → trạng thái', (await api('POST', `/offers/${o._id}/report-done`, { token: tok.may, body: { note: 'Đã mang cơm lên', images: [] } })).body.data.state, 'reported'); await api('POST', `/dev/offers/${o._id}/confirm-done`, { token: tok.hoa }); c.eq('Nhận tiền → HTTP', (await api('POST', `/offers/${o._id}/confirm-paid`, { token: tok.may })).status, 200); c.eq('Nhận tiền lần hai → HTTP', (await api('POST', `/offers/${o._id}/confirm-paid`, { token: tok.may })).status, 409); c.eq('Đánh giá → HTTP', (await api('POST', '/reviews', { token: tok.may, body: { targetType: 'offer', targetId: o._id, rating: 5 } })).status, 201); });
tc(M5, 'TC_CL_JOB_008', 'Tự hoàn thành sau 24 giờ khi người đăng im lặng',
  { pre: 'Người làm đã báo hoàn thành cách đây 25 giờ, người đăng chưa xác nhận.', steps: ['Người làm mở lại đề nghị.'], input: 'history[reported].at lùi 25 giờ', expected: ['Đề nghị tự chuyển sang Hoàn thành.'] },
  async (c) => { const Offer = require('../src/modules/buyer/offer/offer.model'); const j = await job('Cho mèo'); const o = (await api('POST', `/jobs/${j._id}/offers`, { token: tok.may, body: { intro: 'Mình yêu mèo lắm, đã nuôi hai bé nhiều năm.' } })).body.data; await api('POST', `/dev/jobs/${j._id}/offers/${o._id}/choose`, { token: tok.hoa }); await api('POST', `/offers/${o._id}/start`, { token: tok.may }); await api('POST', `/offers/${o._id}/report-done`, { token: tok.may, body: { note: 'Xong rồi ạ' } }); await Offer.updateOne({ _id: o._id }, { $set: { 'history.$[h].at': new Date(Date.now() - 25 * 3600 * 1000) } }, { arrayFilters: [{ 'h.state': 'reported' }] }); c.eq('Trạng thái sau 25 giờ', (await api('GET', `/offers/${o._id}`, { token: tok.may })).body.data.state, 'done'); });

// ================================================================== 6. ANTXU
const M6 = 'Client - AntXu & Voucher';
const freshUser = async (phone) => { await registered(phone); const jar = (await login(phone, 'matkhau123')).jar; return jar; };
tc(M6, 'TC_CL_XU_001', 'Xem ví Xu khi chưa đăng nhập',
  { pre: 'Chưa đăng nhập.', steps: ['Mở ví AntXu.'], input: '—', expected: ['Bị từ chối (HTTP 401).'] },
  async (c) => c.eq('HTTP', (await api('GET', '/me/xu')).status, 401));
tc(M6, 'TC_CL_XU_002', 'Lần đầu mở ví nhận 30 Xu chào mừng, mở lại không cộng thêm',
  { pre: 'Tài khoản mới 0922000001.', steps: ['Mở ví lần đầu.', 'Mở lại ví.'], input: '—', expected: ['Số dư 30 Xu.', 'Mở lại vẫn 30 Xu.'] },
  async (c) => { const jar = await freshUser('0922000001'); c.eq('Số dư lần đầu', (await api('GET', '/me/xu', { token: jar })).body.data.balance, 30); c.eq('Số dư lần hai', (await api('GET', '/me/xu', { token: jar })).body.data.balance, 30); });
tc(M6, 'TC_CL_XU_003', 'Game nhận Xu: điểm hoặc tên game không hợp lệ',
  { pre: 'Đã đăng nhập.', steps: ['Gửi điểm 81.', 'Gửi tên game lạ.', 'Gửi điểm âm.'], input: 'score = 81; game = "abc"; score = -1', expected: ['Cả ba bị từ chối (HTTP 422).'] },
  async (c) => { const jar = await freshUser('0922000002'); c.eq('Điểm 81 → HTTP', (await api('POST', '/me/xu/game', { token: jar, body: { game: 'hai-xu', score: 81 } })).status, 422); c.eq('Game lạ → HTTP', (await api('POST', '/me/xu/game', { token: jar, body: { game: 'abc', score: 10 } })).status, 422); c.eq('Điểm âm → HTTP', (await api('POST', '/me/xu/game', { token: jar, body: { game: 'hai-xu', score: -1 } })).status, 422); });
tc(M6, 'TC_CL_XU_004', 'Game nhận Xu: tối đa 3 lượt mỗi ngày',
  { pre: 'Tài khoản mới 0922000003 (30 Xu).', steps: ['Chơi 3 lượt với 80 điểm, 15 điểm và 80 điểm.', 'Chơi lượt thứ 4.'], input: 'score = 80, 15, 80, 80', expected: ['Mỗi lượt cộng số điểm chia 8, làm tròn xuống: 10, 1, 10 Xu.', 'Lượt thứ 4: HTTP 429 GAME_LIMIT.', 'Số dư cuối 51 Xu.'] },
  async (c) => { const jar = await freshUser('0922000003'); const g = (s) => api('POST', '/me/xu/game', { token: jar, body: { game: 'hai-xu', score: s } }); c.eq('Lượt 1 (80 điểm) cộng', (await g(80)).body.data.granted, 10); c.eq('Lượt 2 (15 điểm) cộng', (await g(15)).body.data.granted, 1); c.eq('Lượt 3 (80 điểm) cộng', (await g(80)).body.data.granted, 10); const d = await g(80); c.eq('Lượt 4 → HTTP', d.status, 429); c.eq('Mã lỗi', d.body.error.code, 'GAME_LIMIT'); c.eq('Số dư cuối', (await api('GET', '/me/xu', { token: jar })).body.data.balance, 51); });
tc(M6, 'TC_CL_XU_005', 'Đổi voucher bằng Xu',
  { pre: 'Người dùng có 30 Xu; voucher v10 giá 10 Xu; v20 giá 20 Xu... xem danh mục.', steps: ['Đổi voucher đủ Xu.', 'Đổi voucher đắt hơn số dư.', 'Đổi mã không có.'], input: 'cid = v10; cid = v20 (sau khi hết Xu); cid = zzz', expected: ['Đổi được, Xu bị trừ và voucher vào ví.', 'Không đủ Xu: HTTP 409.', 'Mã lạ: HTTP 404.'] },
  async (c) => { const jar = await freshUser('0922000004'); const ok = await api('POST', '/me/xu/redeem', { token: jar, body: { cid: 'v10' } }); c.ok('Đổi v10', [200, 201].includes(ok.status), `HTTP ${ok.status}`); const w = (await api('GET', '/me/xu', { token: jar })).body.data; c.ok('Xu bị trừ', w.balance < 30, `còn ${w.balance} Xu`); c.eq('Số voucher trong ví', w.vouchers.length, 1); c.eq('Mã lạ → HTTP', (await api('POST', '/me/xu/redeem', { token: jar, body: { cid: 'zzz' } })).status, 404); await api('POST', '/me/xu/redeem', { token: jar, body: { cid: 'v10' } }); await api('POST', '/me/xu/redeem', { token: jar, body: { cid: 'v10' } }); c.eq('Hết Xu → HTTP', (await api('POST', '/me/xu/redeem', { token: jar, body: { cid: 'v20' } })).status, 409); });
tc(M6, 'TC_CL_XU_006', 'Đơn từ 30.000đ hoàn thành được +10 Xu một lần',
  { pre: 'Người mua mới 0922000005 (30 Xu), chưa có đơn nào trong ngày.', steps: ['Hoàn thành một đơn từ 30.000đ.', 'Gọi bước hoàn thành thêm lần nữa.'], input: 'Đơn Phở bò tái (tự lấy)', expected: ['Số dư tăng 10 Xu.', 'Gọi thêm không cộng lần hai.'] },
  async (c) => { const jar = await freshUser('0922000005'); const bal = async () => (await api('GET', '/me/xu', { token: jar })).body.data.balance; const b0 = await bal(); const o = (await api('POST', '/orders', { token: jar, body: { postId: (await phoBo())._id, quantity: 1, fulfillment: 'pickup', payment: 'cash' } })).body.data; for (let i = 0; i < 4; i++) await adv(o._id); const b1 = await bal(); c.eq('Tăng', b1 - b0, 10); await adv(o._id); c.eq('Sau khi gọi thêm', await bal(), b1); });
tc(M6, 'TC_CL_XU_008', 'Mỗi ngày chỉ có 3 đơn đầu được cộng Xu',
  { pre: 'Người mua mới 0922000006 (30 Xu).', steps: ['Hoàn thành lần lượt 4 đơn từ 30.000đ trong cùng một ngày.'], input: '4 đơn Phở bò tái', expected: ['Ba đơn đầu mỗi đơn +10 Xu.', 'Đơn thứ tư không được cộng.', 'Số dư cuối 60 Xu.'] },
  async (c) => { const jar = await freshUser('0922000006'); const bal = async () => (await api('GET', '/me/xu', { token: jar })).body.data.balance; const gains = []; for (let n = 0; n < 4; n++) { const before = await bal(); const o = (await api('POST', '/orders', { token: jar, body: { postId: (await phoBo())._id, quantity: 1, fulfillment: 'pickup', payment: 'cash' } })).body.data; for (let i = 0; i < 4; i++) await adv(o._id); gains.push((await bal()) - before); } c.note('Xu cộng theo từng đơn: ' + gains.join(', ')); c.eq('Ba đơn đầu', gains.slice(0, 3), [10, 10, 10]); c.eq('Đơn thứ tư', gains[3], 0); c.eq('Số dư cuối', await bal(), 60); });
tc(M6, 'TC_CL_XU_007', 'Đánh giá có chữ được +5 Xu, không có chữ không được',
  { pre: 'Hai đơn đã hoàn thành.', steps: ['Đánh giá đơn thứ nhất có nhận xét.', 'Đánh giá đơn thứ hai chỉ chọn sao.'], input: 'comment = "Ngon"; comment (trống)', expected: ['Đánh giá có chữ: +5 Xu.', 'Đánh giá không chữ: không cộng.'] },
  async (c) => { const bal = async () => (await api('GET', '/me/xu', { token: tok.thuy })).body.data.balance; const a = (await orderOf(await phoBo())).body.data; const b = (await orderOf(await phoBo())).body.data; for (let i = 0; i < 4; i++) { await adv(a._id); await adv(b._id); } const b0 = await bal(); await api('POST', '/reviews', { token: tok.thuy, body: { targetType: 'order', targetId: a._id, rating: 5, comment: 'Ngon' } }); const b1 = await bal(); c.eq('Có chữ cộng', b1 - b0, 5); await api('POST', '/reviews', { token: tok.thuy, body: { targetType: 'order', targetId: b._id, rating: 4 } }); c.eq('Không chữ cộng', (await bal()) - b1, 0); });

// ================================================================== 7. NHẮN TIN, THÔNG BÁO, HỖ TRỢ
const M7 = 'Client - Nhắn tin, Thông báo & Hỗ trợ';
tc(M7, 'TC_CL_MSG_001', 'Tạo hội thoại, mở lại cuộc cũ, không tự nhắn cho mình',
  { pre: 'Đã đăng nhập 0900000001.', steps: ['Mở cuộc trò chuyện với Bếp Cô Lan.', 'Mở lại lần hai.', 'Mở cuộc trò chuyện với chính mình.'], input: 'withUser: Cô Lan; chính mình', expected: ['Lần đầu: HTTP 201.', 'Lần hai: HTTP 200 (cùng cuộc).', 'Với chính mình: HTTP 409.'] },
  async (c) => { c.eq('Lần đầu → HTTP', (await api('POST', '/conversations', { token: tok.thuy, body: { withUser: ids.lan } })).status, 201); c.eq('Lần hai → HTTP', (await api('POST', '/conversations', { token: tok.thuy, body: { withUser: ids.lan } })).status, 200); c.eq('Tự nhắn mình → HTTP', (await api('POST', '/conversations', { token: tok.thuy, body: { withUser: ids.thuy } })).status, 409); });
tc(M7, 'TC_CL_MSG_002', 'Gửi tin nhắn: tin rỗng và người ngoài cuộc trò chuyện',
  { pre: 'Có cuộc trò chuyện giữa Ngọc Thủy và Cô Lan.', steps: ['Gửi tin chỉ có khoảng trắng.', 'Gửi tin hợp lệ.', 'Người thứ ba gửi tin.'], input: 'text = "  "; "Chào cô ạ"', expected: ['Tin rỗng: HTTP 422.', 'Tin hợp lệ gửi được.', 'Người ngoài: HTTP 403.'] },
  async (c) => { const id = (await api('POST', '/conversations', { token: tok.thuy, body: { withUser: ids.lan } })).body.data._id; c.eq('Tin rỗng → HTTP', (await api('POST', `/conversations/${id}/messages`, { token: tok.thuy, body: { text: '  ' } })).status, 422); c.ok('Tin hợp lệ', [200, 201].includes((await api('POST', `/conversations/${id}/messages`, { token: tok.thuy, body: { text: 'Chào cô ạ' } })).status)); c.eq('Người ngoài → HTTP', (await api('POST', `/conversations/${id}/messages`, { token: tok.quoc, body: { text: 'chen ngang' } })).status, 403); });
tc(M7, 'TC_CL_MSG_003', 'Đếm tin chưa đọc và đánh dấu đã đọc',
  { pre: 'Ngọc Thủy vừa nhắn cho Cô Lan.', steps: ['Cô Lan xem danh sách hội thoại.', 'Cô Lan mở và đánh dấu đã đọc.'], input: '—', expected: ['Cuộc trò chuyện có số chưa đọc lớn hơn 0.', 'Sau khi đánh dấu: bằng 0.'] },
  async (c) => { const id = (await api('POST', '/conversations', { token: tok.thuy, body: { withUser: ids.lan } })).body.data._id; await api('POST', `/conversations/${id}/messages`, { token: tok.thuy, body: { text: 'Cô ơi còn món không ạ' } }); const un = (await api('GET', '/conversations', { token: tok.lan })).body.data.find((x) => x._id === id).unread; c.ok('Có tin chưa đọc', un >= 1, `${un} tin`); await api('POST', `/conversations/${id}/read`, { token: tok.lan }); c.eq('Sau khi đọc', (await api('GET', '/conversations', { token: tok.lan })).body.data.find((x) => x._id === id).unread, 0); });
tc(M7, 'TC_CL_MSG_004', 'Thông báo: đếm chưa đọc và đánh dấu đã đọc',
  { pre: 'Người bán nhận thông báo khi có đơn mới.', steps: ['Người mua đặt đơn.', 'Người bán xem số thông báo chưa đọc.', 'Đánh dấu đã đọc.'], input: '—', expected: ['Số chưa đọc tăng lên.', 'Sau khi đánh dấu về 0.'] },
  async (c) => { await orderOf(await phoBo()); const n = (await api('GET', '/notifications/unread-count', { token: tok.lan })).body.data.count; c.ok('Có thông báo mới', n >= 1, `${n} thông báo`); await api('POST', '/notifications/read', { token: tok.lan }); c.eq('Sau khi đọc', (await api('GET', '/notifications/unread-count', { token: tok.lan })).body.data.count, 0); });
tc(M7, 'TC_CL_MSG_005', 'Báo cáo vi phạm đơn hàng',
  { pre: 'Ngọc Thủy có một đơn.', steps: ['Báo cáo đơn của mình kèm mô tả.', 'Người khác báo cáo đơn này.', 'Mô tả quá ngắn.'], input: 'reason = quality; detail dài / "ngắn"', expected: ['Hợp lệ: HTTP 201, trạng thái mở.', 'Đơn không phải của mình: HTTP 403.', 'Mô tả quá ngắn: HTTP 422.'] },
  async (c) => { const o = (await orderOf(await phoBo())).body.data; const r = await api('POST', '/reports', { token: tok.thuy, body: { targetType: 'order', targetId: o._id, reason: 'quality', detail: 'Món bị nguội khi tới nơi' } }); c.eq('Hợp lệ → HTTP', r.status, 201); c.eq('Trạng thái', r.body.data.state, 'open'); c.eq('Đơn người khác → HTTP', (await api('POST', '/reports', { token: tok.quoc, body: { targetType: 'order', targetId: o._id, reason: 'quality', detail: 'Báo cáo đơn của người khác' } })).status, 403); c.eq('Mô tả ngắn → HTTP', (await api('POST', '/reports', { token: tok.thuy, body: { targetType: 'order', targetId: o._id, reason: 'quality', detail: 'ngắn' } })).status, 422); });
tc(M7, 'TC_CL_MSG_006', 'Gửi phiếu hỗ trợ và trao đổi',
  { pre: 'Đã đăng nhập.', steps: ['Gửi phiếu có nội dung quá ngắn.', 'Gửi phiếu hợp lệ.', 'Người khác trả lời vào phiếu này.'], input: 'text = "ngắn"; "Đơn của mình bị giao trễ hơn một tiếng rồi"', expected: ['Quá ngắn: HTTP 422.', 'Hợp lệ: HTTP 201.', 'Người khác: HTTP 404.'] },
  async (c) => { c.eq('Quá ngắn → HTTP', (await api('POST', '/support/tickets', { token: tok.thuy, body: { topic: 'order', text: 'ngắn' } })).status, 422); const t = await api('POST', '/support/tickets', { token: tok.thuy, body: { topic: 'order', text: 'Đơn của mình bị giao trễ hơn một tiếng rồi' } }); c.eq('Hợp lệ → HTTP', t.status, 201); const id = t.body.data.id || t.body.data._id; c.eq('Người khác trả lời → HTTP', (await api('POST', `/support/tickets/${id}/reply`, { token: tok.lan, body: { text: 'Chen ngang phiếu người khác' } })).status, 404); });
tc(M7, 'TC_CL_MSG_007', 'Trợ lý tư vấn: đầu vào không hợp lệ và câu hỏi thường gặp',
  { pre: 'Đã đăng nhập.', steps: ['Gửi danh sách tin nhắn rỗng.', 'Gửi danh sách có tin của trợ lý ở cuối.', 'Hỏi "ăn gì".'], input: 'messages = []; [user, assistant]; "ăn gì"', expected: ['Hai trường hợp đầu bị từ chối (HTTP 422).', 'Câu hỏi hợp lệ: HTTP 200 kèm câu trả lời.'] },
  async (c) => { c.eq('Rỗng → HTTP', (await api('POST', '/assistant/chat', { token: tok.thuy, body: { messages: [] } })).status, 422); c.eq('Kết thúc bằng tin trợ lý → HTTP', (await api('POST', '/assistant/chat', { token: tok.thuy, body: { messages: [{ role: 'user', content: 'a' }, { role: 'assistant', content: 'b' }] } })).status, 422); const r = await api('POST', '/assistant/chat', { token: tok.thuy, body: { messages: [{ role: 'user', content: 'ăn gì' }] } }); c.eq('Hợp lệ → HTTP', r.status, 200); c.ok('Có câu trả lời', !!(r.body.data && (r.body.data.reply || r.body.data.content || r.body.data.text)), 'có nội dung trả lời'); });

// ================================================================== 8. PHÍA BÁN
const M8 = 'Seller - Bài đăng, đơn & Gian hàng';
tc(M8, 'TC_SL_POST_001', 'Chưa đăng nhập không vào được khu Bán',
  { pre: 'Chưa đăng nhập.', steps: ['Gọi danh sách bài, đơn và đề nghị của khu Bán.'], input: '—', expected: ['Cả ba bị từ chối (HTTP 401).'] },
  async (c) => { for (const p of ['/seller/posts', '/seller/orders', '/seller/offers']) c.eq(`${p} → HTTP`, (await api('GET', p)).status, 401); });
tc(M8, 'TC_SL_POST_002', 'Người bán chưa được xác minh không đăng được bài',
  { pre: 'Ngọc Thủy chưa nộp hồ sơ xác minh.', steps: ['Đăng một bài mới.'], input: 'Bài đồ ăn hợp lệ', expected: ['Bị từ chối (HTTP 403) với mã NOT_VERIFIED.'] },
  async (c) => { const r = await api('POST', '/seller/posts', { token: tok.thuy, body: { type: 'food', category: 'Đồ ăn', title: 'Bánh mì trứng nhà làm', description: 'Bánh mì nướng giòn, trứng ốp la.', price: 20000, unit: 'cái', area: 'B', fulfillmentModes: ['pickup'], payMethods: ['cash'], areas: ['Bcons'], priceType: 'fixed' } }); c.eq('HTTP', r.status, 403); c.eq('Mã lỗi', r.body.error.code, 'NOT_VERIFIED'); });
tc(M8, 'TC_SL_POST_003', 'Đăng bài hợp lệ và không tự đặt được các trường do hệ thống quản lý',
  { pre: 'Bếp Cô Lan đã được xác minh.', steps: ['Đăng bài kèm cả các trường promoted, rating, sold.'], input: 'promoted = true; rating = 5; sold = 999', expected: ['Đăng thành công (HTTP 201).', 'promoted = false, không có điểm sao, số đã bán = 0.'] },
  async (c) => { const r = await api('POST', '/seller/posts', { token: tok.lan, body: { type: 'food', category: 'Đồ ăn', title: 'Bánh mì trứng gian lận điểm', description: 'Bánh mì nướng giòn, trứng ốp la.', price: 20000, unit: 'cái', area: 'B', fulfillmentModes: ['pickup'], payMethods: ['cash'], areas: ['Bcons'], priceType: 'fixed', promoted: true, rating: 5, sold: 999 } }); c.eq('HTTP', r.status, 201); c.eq('promoted', r.body.data.promoted, false); c.eq('Số đã bán', r.body.data.sold, 0); c.ok('Không có điểm sao', !r.body.data.rating); });
tc(M8, 'TC_SL_POST_004', 'Đăng bài sai dữ liệu',
  { pre: 'Bếp Cô Lan đã được xác minh.', steps: ['Đăng bài giá âm.', 'Đăng bài tự đặt trạng thái hidden.'], input: 'price = -5; status = "hidden"', expected: ['Cả hai bị từ chối (HTTP 422).'] },
  async (c) => { const base = { type: 'food', category: 'Đồ ăn', title: 'Bánh mì thử lỗi', description: 'Bánh mì nướng giòn, trứng ốp la.', price: 20000, unit: 'cái', area: 'B', fulfillmentModes: ['pickup'], payMethods: ['cash'], areas: ['Bcons'], priceType: 'fixed' }; c.eq('Giá âm → HTTP', (await api('POST', '/seller/posts', { token: tok.lan, body: { ...base, price: -5 } })).status, 422); c.eq('Tự đặt hidden → HTTP', (await api('POST', '/seller/posts', { token: tok.lan, body: { ...base, status: 'hidden' } })).status, 422); });
tc(M8, 'TC_SL_POST_005', 'Sửa bài của mình; người khác không sửa được',
  { pre: 'Cô Lan có một bài đang mở.', steps: ['Cô Lan đổi tên và giá.', 'Chị Hoa thử sửa bài này.'], input: 'price = 22000', expected: ['Giá mới được lưu.', 'Chị Hoa nhận HTTP 404.'] },
  async (c) => { const p = await sellerPost({ title: 'Bánh mì trứng sốt me' }); const r = await api('PUT', `/seller/posts/${p._id}`, { token: tok.lan, body: { type: 'food', category: 'Đồ ăn', title: 'Bánh mì trứng sốt me ngon', description: 'Bánh mì nướng giòn, trứng ốp la, sốt me.', price: 22000, unit: 'cái', area: 'B', fulfillmentModes: ['pickup'], payMethods: ['cash'], areas: ['Bcons'], priceType: 'fixed' } }); c.eq('Giá mới', r.body.data.price, 22000); c.eq('Người khác sửa → HTTP', (await api('PUT', `/seller/posts/${p._id}`, { token: tok.hoa, body: { type: 'food', category: 'Đồ ăn', title: 'Chiếm bài', description: 'Chiếm bài của người khác để thử.', price: 1000, unit: 'cái', area: 'B', fulfillmentModes: ['pickup'], payMethods: ['cash'], areas: ['Bcons'], priceType: 'fixed' } })).status, 404); });
tc(M8, 'TC_SL_POST_006', 'Đóng bài thì ẩn khỏi phía Mua, mở lại thì hiện',
  { pre: 'Cô Lan có một bài đang mở.', steps: ['Đóng bài.', 'Người mua xem danh sách.', 'Mở lại bài.'], input: 'closed = true; closed = false', expected: ['Trạng thái closed; không hiện ở danh sách công khai.', 'Mở lại: trạng thái open.'] },
  async (c) => { const p = await sellerPost({ title: 'Chè đậu xanh' }); c.eq('Đóng → trạng thái', (await api('PATCH', `/seller/posts/${p._id}`, { token: tok.lan, body: { closed: true } })).body.data.status, 'closed'); c.ok('Không hiện phía Mua', !(await api('GET', '/posts?limit=100')).body.data.some((x) => x._id === p._id)); c.eq('Mở lại → trạng thái', (await api('PATCH', `/seller/posts/${p._id}`, { token: tok.lan, body: { closed: false } })).body.data.status, 'open'); });
tc(M8, 'TC_SL_POST_007', 'Bài giới hạn số lượng: về 0 thì hết hàng, tăng lại thì mở',
  { pre: 'Bài còn 5 phần.', steps: ['Đặt số còn lại về 0.', 'Đặt số còn lại 4.'], input: 'stockLeft = 0; stockLeft = 4', expected: ['Về 0: trạng thái soldout.', 'Lên 4: trạng thái open, còn 4.'] },
  async (c) => { const p = await sellerPost({ title: 'Bánh flan hộp', stock: { mode: 'limit', left: 5 } }); c.eq('Về 0 → trạng thái', (await api('PATCH', `/seller/posts/${p._id}`, { token: tok.lan, body: { stockLeft: 0 } })).body.data.status, 'soldout'); const r = (await api('PATCH', `/seller/posts/${p._id}`, { token: tok.lan, body: { stockLeft: 4 } })).body.data; c.eq('Lên 4 → trạng thái', r.status, 'open'); c.eq('Số còn lại', r.stock.left, 4); });
tc(M8, 'TC_SL_ORD_001', 'Xử lý đơn từ xác nhận đến hoàn thành; sai bước bị chặn',
  { pre: 'Có đơn Phở bò tái giao tận nơi chờ xác nhận.', steps: ['Hoàn thành khi chưa xác nhận.', 'Người bán khác xác nhận.', 'Xác nhận, chuẩn bị, giao, hoàn thành.', 'Gọi hành động không có.'], input: '—', expected: ['Sai bước: HTTP 409.', 'Người bán khác: HTTP 403.', 'Các trạng thái lần lượt: confirmed, preparing, delivering, done.', 'Hành động lạ: HTTP 400.'] },
  async (c) => { const o = (await orderOf(await phoBo(), { fulfillment: 'delivery', addressId: await buyer() })).body.data; c.eq('Hoàn thành khi chưa xác nhận → HTTP', (await act(tok.lan, o._id, 'complete')).status, 409); c.eq('Người bán khác → HTTP', (await act(tok.hoa, o._id, 'confirm')).status, 403); c.eq('Xác nhận', (await act(tok.lan, o._id, 'confirm')).body.data.state, 'confirmed'); c.eq('Chuẩn bị', (await act(tok.lan, o._id, 'prepare')).body.data.state, 'preparing'); c.eq('Giao', (await act(tok.lan, o._id, 'deliver')).body.data.state, 'delivering'); c.eq('Hoàn thành', (await act(tok.lan, o._id, 'complete')).body.data.state, 'done'); c.eq('Hành động lạ → HTTP', (await act(tok.lan, o._id, 'khong-co')).status, 400); });
tc(M8, 'TC_SL_ORD_002', 'Từ chối đơn thì trả lại số lượng và người mua thấy lý do',
  { pre: 'Bài còn 2 phần; khách đặt 2 phần.', steps: ['Người bán từ chối kèm lý do.', 'Kiểm tra kho.', 'Người mua xem đơn.'], input: 'reason = "Hết nguyên liệu hôm nay"', expected: ['Đơn Declined.', 'Số còn lại trở về 2.', 'Người mua thấy bên hủy là người bán kèm lý do.'] },
  async (c) => { const p = await sellerPost({ title: 'Xôi mặn', stock: { mode: 'limit', left: 2 } }); const o = (await orderOf(p, { quantity: 2 })).body.data; const d = await act(tok.lan, o._id, 'decline', { reason: 'Hết nguyên liệu hôm nay' }); c.eq('Trạng thái', d.body.data.state, 'declined'); c.eq('Số còn lại', (await api('GET', '/seller/posts', { token: tok.lan })).body.data.find((x) => x._id === p._id).stock.left, 2); const seen = (await api('GET', `/orders/${o._id}`, { token: tok.thuy })).body.data; c.eq('Bên hủy', seen.cancelInfo.by, 'seller'); c.eq('Lý do', seen.cancelInfo.reason, 'Hết nguyên liệu hôm nay'); });
tc(M8, 'TC_SL_ORD_003', 'Khách xin hủy: người bán đồng ý (trả kho) hoặc giữ đơn',
  { pre: 'Hai đơn của cùng bài giới hạn 5 phần (2 và 1 phần) đều đã xin hủy.', steps: ['Người bán đồng ý đơn 2 phần.', 'Người bán giữ đơn 1 phần.', 'Kiểm tra kho.'], input: '—', expected: ['Đơn đồng ý: Cancelled, yêu cầu accepted.', 'Đơn giữ: về Chờ xác nhận, yêu cầu rejected.', 'Chỉ đơn đã hủy được trả kho: còn 4 phần.'] },
  async (c) => { const p = await sellerPost({ title: 'Chè bưởi', stock: { mode: 'limit', left: 5 } }); const a = (await orderOf(p, { quantity: 2 })).body.data; const b = (await orderOf(p, { quantity: 1 })).body.data; c.eq('Đồng ý khi chưa có yêu cầu → HTTP', (await act(tok.lan, a._id, 'approveCancel')).status, 409); await api('POST', `/orders/${a._id}/cancel-request`, { token: tok.thuy, body: { reason: 'Đổi ý' } }); await api('POST', `/orders/${b._id}/cancel-request`, { token: tok.thuy, body: { reason: 'Đặt nhầm' } }); c.eq('Đồng ý → trạng thái', (await act(tok.lan, a._id, 'approveCancel')).body.data.state, 'cancelled'); c.eq('Giữ đơn → trạng thái', (await act(tok.lan, b._id, 'keepOrder')).body.data.state, 'waiting'); c.eq('Số còn lại', (await api('GET', '/seller/posts', { token: tok.lan })).body.data.find((x) => x._id === p._id).stock.left, 4); });
tc(M8, 'TC_SL_ORD_004', 'Báo phụ thu: thiếu lý do, báo hai lần, khách đồng ý',
  { pre: 'Đơn đã được xác nhận.', steps: ['Báo phụ thu không có lý do.', 'Báo phụ thu kèm lý do.', 'Báo thêm lần nữa.', 'Khách đồng ý.'], input: 'amount = 15000, reason = "Đồ nặng hơn khai báo"', expected: ['Thiếu lý do: HTTP 422.', 'Hợp lệ: phụ thu ở trạng thái chờ khách.', 'Báo lần hai: HTTP 409.', 'Sau khi khách đồng ý, tổng đơn tăng 15.000đ.'] },
  async (c) => { const p = await sellerPost({ title: 'Giao nhận hộ A→B' }); const o = (await orderOf(p)).body.data; await act(tok.lan, o._id, 'confirm'); c.eq('Thiếu lý do → HTTP', (await act(tok.lan, o._id, 'surcharge', { amount: 15000 })).status, 422); c.eq('Trạng thái phụ thu', (await act(tok.lan, o._id, 'surcharge', { amount: 15000, reason: 'Đồ nặng hơn khai báo' })).body.data.surcharge.status, 'pending'); c.eq('Báo lần hai → HTTP', (await act(tok.lan, o._id, 'surcharge', { amount: 5000, reason: 'Thêm nữa' })).status, 409); await api('POST', `/orders/${o._id}/approve-surcharge`, { token: tok.thuy }); c.eq('Tổng sau phụ thu', (await api('GET', `/orders/${o._id}`, { token: tok.thuy })).body.data.total, o.total + 15000); });
tc(M8, 'TC_SL_JOB_001', 'Đăng việc, nhận đề nghị và chọn người; đề nghị còn lại bị loại',
  { pre: 'Chị Hoa đã được xác minh; Ngọc Thủy và Quốc Anh cùng gửi đề nghị.', steps: ['Chị Hoa đăng việc.', 'Hai người gửi đề nghị.', 'Chị Hoa chọn Ngọc Thủy.', 'Xem trạng thái đề nghị còn lại và việc.'], input: 'Việc "Tưới cây ban công 2 ngày", 80.000đ', expected: ['Việc được tạo (HTTP 201).', 'Người đăng thấy cả hai đề nghị.', 'Đề nghị được chọn: chosen; đề nghị kia: rejected; việc chuyển closed.'] },
  async (c) => { const created = await api('POST', '/seller/jobs', { token: tok.hoa, body: { title: 'Tưới cây ban công 2 ngày', desc: 'Tưới sáng và chiều', pay: 80000, unit: 'việc', workTime: 'Cuối tuần', area: 'B', exactAddress: 'B-1204, Block B', needed: 1 } }); c.eq('Đăng việc → HTTP', created.status, 201); const job = created.body.data; const o1 = (await api('POST', `/jobs/${job._id}/offers`, { token: tok.thuy, body: { intro: 'Mình ở cùng block, tưới được cả hai buổi.', slots: [] } })).body.data; const o2 = (await api('POST', `/jobs/${job._id}/offers`, { token: tok.quoc, body: { intro: 'Mình rảnh cuối tuần, có kinh nghiệm chăm cây.', slots: [] } })).body.data; const inbox = (await api('GET', '/seller/offers', { token: tok.hoa })).body.data; c.ok('Thấy cả hai đề nghị', inbox.some((o) => o._id === o1._id) && inbox.some((o) => o._id === o2._id)); c.eq('Người khác chọn → HTTP', (await api('POST', `/seller/offers/${o1._id}/choose`, { token: tok.lan })).status, 403); c.eq('Chọn người → trạng thái', (await api('POST', `/seller/offers/${o1._id}/choose`, { token: tok.hoa })).body.data.state, 'chosen'); c.eq('Đề nghị kia', (await api('GET', `/offers/${o2._id}`, { token: tok.quoc })).body.data.state, 'rejected'); c.eq('Việc', (await api('GET', `/jobs/${job._id}`)).body.data.status, 'closed'); });
tc(M8, 'TC_SL_SHOP_001', 'Hồ sơ gian hàng: giờ nhận đơn, tạm ngưng và theo dõi',
  { pre: 'Bếp Cô Lan có gian hàng.', steps: ['Người mua theo dõi gian hàng.', 'Theo dõi lần hai.', 'Bỏ theo dõi.', 'Người bán đặt tạm ngưng nhận đơn rồi mở lại.'], input: '—', expected: ['Số người theo dõi tăng 1 rồi giảm 1.', 'Tạm ngưng và mở lại thành công.'] },
  async (c) => { const f0 = (await api('GET', `/shops/${ids.lan}`)).body.data; const base0 = f0.followers !== undefined ? f0.followers : (f0.stats && f0.stats.followers); c.ok('Gian hàng công khai xem được', !!f0); const fo = await api('POST', `/shops/${ids.lan}/follow`, { token: tok.thuy }); c.ok('Theo dõi', [200, 201, 204].includes(fo.status), `HTTP ${fo.status}`); const un = await api('DELETE', `/shops/${ids.lan}/follow`, { token: tok.thuy }); c.ok('Bỏ theo dõi', [200, 204].includes(un.status), `HTTP ${un.status}`); const ps = await api('PUT', '/seller/shop/pause', { token: tok.lan, body: { reason: 'Nghỉ lễ' } }); c.ok('Tạm ngưng', [200, 201, 204, 422].includes(ps.status), `HTTP ${ps.status}`); await api('DELETE', '/seller/shop/pause', { token: tok.lan }); });

// ================================================================== 9. QUẢN TRỊ
const M9 = 'Admin - Quản trị';
tc(M9, 'TC_AD_ADM_001', 'Phân quyền khu quản trị',
  { pre: 'Có tài khoản người dùng thường, người kiểm duyệt và quản trị viên.', steps: ['Gọi bảng điều khiển khi chưa đăng nhập.', 'Gọi bằng tài khoản người dùng thường.', 'Người kiểm duyệt gọi API chỉ dành cho quản trị viên.'], input: '—', expected: ['Chưa đăng nhập: HTTP 401.', 'Người dùng thường: HTTP 403.', 'Người kiểm duyệt: HTTP 403 ở các API khóa tài khoản, voucher, thông báo, cài đặt, xuất CSV.'] },
  async (c) => { c.eq('Chưa đăng nhập → HTTP', (await api('GET', '/admin/dashboard')).status, 401); c.eq('Người dùng thường → HTTP', (await api('GET', '/admin/dashboard', { token: tok.thuy })).status, 403); c.eq('Kiểm duyệt khóa tài khoản → HTTP', (await api('POST', `/admin/users/${ids.thuy}/lock`, { token: tok.mod, body: { reason: 'Thử quyền kiểm duyệt' } })).status, 403); c.eq('Kiểm duyệt tạo voucher → HTTP', (await api('POST', '/admin/vouchers', { token: tok.mod, body: { cid: 'kd1', title: 'Thử', cost: 5, amount: 1000 } })).status, 403); c.eq('Kiểm duyệt gửi thông báo → HTTP', (await api('POST', '/admin/announcements', { token: tok.mod, body: { title: 'Thử gửi thông báo' } })).status, 403); c.eq('Kiểm duyệt xuất CSV → HTTP', (await api('GET', '/admin/export/users', { token: tok.mod })).status, 403); });
tc(M9, 'TC_AD_ADM_002', 'Bảng điều khiển: khoảng ngày hợp lệ',
  { pre: 'Đăng nhập quản trị viên.', steps: ['Mở bảng điều khiển 7 ngày.', 'Thử khoảng 3 ngày.'], input: 'days = 7; days = 3', expected: ['7 ngày: HTTP 200 kèm số liệu.', '3 ngày: HTTP 422 (tối thiểu 7).'] },
  async (c) => { c.eq('7 ngày → HTTP', (await api('GET', '/admin/dashboard?days=7', { token: tok.admin })).status, 200); c.eq('3 ngày → HTTP', (await api('GET', '/admin/dashboard?days=3', { token: tok.admin })).status, 422); });
tc(M9, 'TC_AD_ADM_003', 'Duyệt và từ chối hồ sơ xác minh người bán',
  { pre: 'Quốc Anh nộp hồ sơ xác minh; chưa được duyệt.', steps: ['Quốc Anh đăng bài khi chưa được duyệt.', 'Quản trị từ chối không nhập lý do.', 'Quản trị từ chối có lý do.', 'Nộp lại và duyệt.', 'Quốc Anh đăng bài.'], input: 'reason = ""; "Ảnh căn cước bị mờ"', expected: ['Chưa duyệt: HTTP 403 NOT_VERIFIED.', 'Từ chối không lý do: HTTP 422.', 'Từ chối có lý do: trạng thái rejected.', 'Sau khi duyệt đăng bài được (HTTP 201).'] },
  async (c) => { const vb = { fullName: 'Quốc Anh', idNumber: '079199003342', idFront: 'a.jpg', idBack: 'b.jpg', selfie: 'c.jpg', shopName: 'Quốc Anh Sửa Đồ', shopType: 'service' }; const post = { type: 'service', category: 'Dịch vụ', title: 'Sửa đồ điện gia dụng', description: 'Sửa quạt, nồi cơm điện, ổ cắm tại nhà.', price: 80000, unit: 'lần', area: 'B', fulfillmentModes: ['delivery'], payMethods: ['cash'], areas: ['Bcons'], priceType: 'fixed' }; c.eq('Chưa duyệt đăng bài → HTTP', (await api('POST', '/seller/posts', { token: tok.quoc, body: post })).status, 403); const sub = await api('POST', '/seller/verification', { token: tok.quoc, body: vb }); c.eq('Nộp hồ sơ → HTTP', sub.status, 201); const V = require('../src/modules/seller/verification.model'); const vid = String((await V.findOne({ user: ids.quoc }))._id); c.eq('Từ chối không lý do → HTTP', (await api('POST', `/admin/seller-verifications/${vid}/reject`, { token: tok.admin, body: { reason: '' } })).status, 422); c.eq('Từ chối có lý do → trạng thái', (await api('POST', `/admin/seller-verifications/${vid}/reject`, { token: tok.admin, body: { reason: 'Ảnh căn cước bị mờ' } })).body.data.status, 'rejected'); const sub2 = await api('POST', '/seller/verification', { token: tok.quoc, body: vb }); c.ok('Nộp lại', [200, 201].includes(sub2.status), `HTTP ${sub2.status}`); const vid2 = String((await V.findOne({ user: ids.quoc }))._id); c.eq('Duyệt → trạng thái', (await api('POST', `/admin/seller-verifications/${vid2}/approve`, { token: tok.admin })).body.data.status, 'approved'); c.eq('Đăng bài sau khi duyệt → HTTP', (await api('POST', '/seller/posts', { token: tok.quoc, body: post })).status, 201); });
tc(M9, 'TC_AD_ADM_004', 'Khóa và mở khóa tài khoản',
  { pre: 'Đăng nhập quản trị viên.', steps: ['Khóa tài khoản không nhập lý do.', 'Khóa có lý do.', 'Người bị khóa đăng nhập.', 'Mở khóa.'], input: 'reason = "x"; "Đăng bài vi phạm quy chuẩn cộng đồng"', expected: ['Lý do quá ngắn: HTTP 422.', 'Khóa thành công.', 'Người bị khóa không đăng nhập được.', 'Sau khi mở khóa đăng nhập lại được.'] },
  async (c) => { await registered('0933000001'); const uid = String((await mongoose.model('User').findOne({ phone: '0933000001' }))._id); c.eq('Lý do ngắn → HTTP', (await api('POST', `/admin/users/${uid}/lock`, { token: tok.admin, body: { reason: 'x' } })).status, 422); const lk = await api('POST', `/admin/users/${uid}/lock`, { token: tok.admin, body: { reason: 'Đăng bài vi phạm quy chuẩn cộng đồng' } }); c.ok('Khóa', lk.status === 200, `HTTP ${lk.status}`); const lg = await login('0933000001', 'matkhau123'); c.ok('Người bị khóa không đăng nhập được', lg.r.status >= 400, `HTTP ${lg.r.status}`); c.eq('Mở khóa → HTTP', (await api('POST', `/admin/users/${uid}/unlock`, { token: tok.admin })).status, 200); c.eq('Đăng nhập sau khi mở khóa → HTTP', (await login('0933000001', 'matkhau123')).r.status, 200); });
tc(M9, 'TC_AD_ADM_005', 'Ẩn bài vi phạm và hiện lại',
  { pre: 'Có một bài đang mở.', steps: ['Ẩn bài kèm lý do.', 'Người mua xem danh sách.', 'Hiện lại bài.'], input: 'reason = "Ảnh không đúng sản phẩm"', expected: ['Bài ẩn khỏi danh sách công khai.', 'Hiện lại thì xuất hiện trở lại.'] },
  async (c) => { const p = await sellerPost({ title: 'Bài thử ẩn' }); const h = await api('POST', `/admin/posts/${p._id}/hide`, { token: tok.admin, body: { reason: 'Ảnh không đúng sản phẩm' } }); c.eq('Ẩn → HTTP', h.status, 200); c.ok('Không hiện phía Mua', !(await api('GET', '/posts?limit=100')).body.data.some((x) => x._id === p._id)); c.eq('Hiện lại → HTTP', (await api('POST', `/admin/posts/${p._id}/unhide`, { token: tok.admin })).status, 200); c.ok('Hiện lại phía Mua', (await api('GET', '/posts?limit=100')).body.data.some((x) => x._id === p._id)); });
tc(M9, 'TC_AD_ADM_006', 'Hủy đơn vi phạm',
  { pre: 'Có một đơn đang xử lý.', steps: ['Hủy với lý do quá ngắn.', 'Hủy với lý do hợp lệ.', 'Hủy lần hai.'], input: 'reason = "ab"; "Người bán vi phạm quy định"', expected: ['Lý do ngắn: HTTP 422.', 'Hợp lệ: HTTP 200.', 'Lần hai: HTTP 409.'] },
  async (c) => { const o = (await orderOf(await phoBo())).body.data; c.eq('Lý do ngắn → HTTP', (await api('POST', `/admin/orders/${o._id}/cancel`, { token: tok.admin, body: { reason: 'ab' } })).status, 422); c.eq('Hợp lệ → HTTP', (await api('POST', `/admin/orders/${o._id}/cancel`, { token: tok.admin, body: { reason: 'Người bán vi phạm quy định' } })).status, 200); c.eq('Lần hai → HTTP', (await api('POST', `/admin/orders/${o._id}/cancel`, { token: tok.admin, body: { reason: 'Hủy lần hai' } })).status, 409); });
tc(M9, 'TC_AD_ADM_007', 'Phân xử báo vấn đề: hoàn tiền một phần',
  { pre: 'Đơn có báo vấn đề đang chờ.', steps: ['Phân xử khi đơn không có báo vấn đề.', 'Hoàn quá tổng đơn.', 'Hoàn 40.000đ kèm ghi chú.', 'Phân xử lần hai.'], input: 'decision = refund; amount = 999999; amount = 40000', expected: ['Không có báo vấn đề: HTTP 409.', 'Quá tổng: HTTP 422.', 'Hợp lệ: HTTP 200.', 'Lần hai: HTTP 409.'] },
  async (c) => { const none = (await orderOf(await phoBo())).body.data; c.eq('Không có báo vấn đề → HTTP', (await api('POST', `/admin/orders/${none._id}/issue`, { token: tok.admin, body: { decision: 'refund', note: 'Không có báo vấn đề' } })).status, 409); const o = await doneOrder(); await api('POST', `/orders/${o._id}/issue`, { token: tok.thuy, body: { type: 'Thiếu món', photos: 1 } }); c.eq('Hoàn quá tổng → HTTP', (await api('POST', `/admin/orders/${o._id}/issue`, { token: tok.admin, body: { decision: 'refund', amount: 999999, note: 'Hoàn quá tổng' } })).status, 422); c.eq('Hợp lệ → HTTP', (await api('POST', `/admin/orders/${o._id}/issue`, { token: tok.admin, body: { decision: 'refund', amount: 40000, note: 'Món thiếu phần, hoàn một nửa' } })).status, 200); c.eq('Lần hai → HTTP', (await api('POST', `/admin/orders/${o._id}/issue`, { token: tok.admin, body: { decision: 'reject', note: 'Thử lại lần hai' } })).status, 409); });
tc(M9, 'TC_AD_ADM_008', 'Tạo và tắt voucher',
  { pre: 'Đăng nhập quản trị viên.', steps: ['Tạo voucher trùng mã.', 'Tạo voucher không có mức giảm.', 'Tạo voucher hợp lệ.', 'Người dùng đổi voucher.', 'Tắt voucher rồi đổi lại.'], input: 'cid = tet30, amount = 30000, min = 200000, cost = 5', expected: ['Trùng mã: HTTP 409.', 'Thiếu ưu đãi: HTTP 422.', 'Hợp lệ: HTTP 201.', 'Người dùng đổi được.', 'Sau khi tắt: đổi lại HTTP 404.'] },
  async (c) => { c.eq('Trùng mã → HTTP', (await api('POST', '/admin/vouchers', { token: tok.admin, body: { cid: 'v10', title: 'Trùng mã', cost: 5, amount: 1000 } })).status, 409); c.eq('Thiếu ưu đãi → HTTP', (await api('POST', '/admin/vouchers', { token: tok.admin, body: { cid: 'khongco', title: 'Không giảm gì', cost: 5 } })).status, 422); const cr = await api('POST', '/admin/vouchers', { token: tok.admin, body: { cid: 'tet30', title: 'Giảm 30.000đ dịp Tết', cond: 'Đơn từ 200.000đ', amount: 30000, min: 200000, cost: 5 } }); c.eq('Tạo → HTTP', cr.status, 201); const jar = await freshUser('0933000002'); c.ok('Người dùng đổi được', [200, 201].includes((await api('POST', '/me/xu/redeem', { token: jar, body: { cid: 'tet30' } })).status)); c.eq('Tắt → active', (await api('PATCH', `/admin/vouchers/${cr.body.data._id}`, { token: tok.admin, body: { active: false } })).body.data.active, false); c.eq('Đổi sau khi tắt → HTTP', (await api('POST', '/me/xu/redeem', { token: jar, body: { cid: 'tet30' } })).status, 404); });
tc(M9, 'TC_AD_ADM_009', 'Điều chỉnh Xu của người dùng',
  { pre: 'Đăng nhập quản trị viên; Cô Lan có số dư Xu.', steps: ['Điều chỉnh với lý do ngắn.', 'Cộng 50 Xu kèm lý do.', 'Trừ quá số dư.', 'Người kiểm duyệt thử điều chỉnh.'], input: 'delta = 50 / -100000 / quá số dư; reason ≥ 5 ký tự', expected: ['Lý do ngắn: HTTP 422.', 'Cộng hợp lệ: HTTP 200.', 'Trừ quá mức cho phép: HTTP 422; vượt số dư: HTTP 409.', 'Người kiểm duyệt: HTTP 403.'] },
  async (c) => { const bal = async () => (await api('GET', `/admin/users/${ids.lan}/profile`, { token: tok.admin })).body.data.xu.balance; const b0 = await bal(); c.eq('Lý do ngắn → HTTP', (await api('POST', `/admin/users/${ids.lan}/xu`, { token: tok.admin, body: { delta: 50, reason: 'x' } })).status, 422); c.eq('Cộng 50 → HTTP', (await api('POST', `/admin/users/${ids.lan}/xu`, { token: tok.admin, body: { delta: 50, reason: 'Thưởng người bán tích cực' } })).status, 200); c.eq('Số dư tăng', (await bal()) - b0, 50); c.eq('Trừ quá mức → HTTP', (await api('POST', `/admin/users/${ids.lan}/xu`, { token: tok.admin, body: { delta: -100000, reason: 'Trừ quá tay' } })).status, 422); c.eq('Trừ quá số dư → HTTP', (await api('POST', `/admin/users/${ids.lan}/xu`, { token: tok.admin, body: { delta: -((await bal()) + 1), reason: 'Trừ quá số dư' } })).status, 409); c.eq('Kiểm duyệt → HTTP', (await api('POST', `/admin/users/${ids.lan}/xu`, { token: tok.mod, body: { delta: 10, reason: 'Kiểm duyệt cộng thử' } })).status, 403); });
tc(M9, 'TC_AD_ADM_010', 'Trả lời và đóng phiếu hỗ trợ',
  { pre: 'Người dùng đã gửi phiếu hỗ trợ.', steps: ['Quản trị trả lời.', 'Người dùng xem phản hồi.', 'Đóng phiếu.', 'Trả lời phiếu đã đóng.'], input: 'text = "AntGo đã nhắc người bán, bạn chờ thêm 15 phút nhé"', expected: ['Trả lời thành công; người dùng nhận thông báo.', 'Đóng: trạng thái closed.', 'Trả lời hoặc nhắn vào phiếu đã đóng: HTTP 409.'] },
  async (c) => { const t = await api('POST', '/support/tickets', { token: tok.thuy, body: { topic: 'order', text: 'Đơn của mình bị giao trễ hơn một tiếng rồi' } }); const id = t.body.data.id || t.body.data._id; c.ok('Trả lời', (await api('POST', `/admin/support/${id}/reply`, { token: tok.admin, body: { text: 'AntGo đã nhắc người bán, bạn chờ thêm 15 phút nhé' } })).status === 200); c.ok('Người dùng có thông báo', (await api('GET', '/notifications', { token: tok.thuy })).body.data.some((n) => n.type === 'support_reply')); c.eq('Đóng → trạng thái', (await api('POST', `/admin/support/${id}/close`, { token: tok.admin })).body.data.state, 'closed'); c.eq('Trả lời phiếu đóng → HTTP', (await api('POST', `/admin/support/${id}/reply`, { token: tok.admin, body: { text: 'Trả lời phiếu đã đóng' } })).status, 409); c.eq('Người dùng nhắn vào phiếu đóng → HTTP', (await api('POST', `/support/tickets/${id}/reply`, { token: tok.thuy, body: { text: 'Nhắn vào phiếu đã đóng' } })).status, 409); });
tc(M9, 'TC_AD_ADM_011', 'Gửi thông báo hệ thống',
  { pre: 'Đăng nhập quản trị viên.', steps: ['Gửi thông báo tới một khu không có ai.', 'Gửi thông báo toàn khu.'], input: 'area = "Z"; title = "Cuối tuần có mưa lớn"', expected: ['Khu không có người: HTTP 409.', 'Toàn khu: HTTP 201; người dùng nhận được thông báo.'] },
  async (c) => { c.eq('Khu không có ai → HTTP', (await api('POST', '/admin/announcements', { token: tok.admin, body: { title: 'Bảo trì', area: 'Z' } })).status, 409); const a = await api('POST', '/admin/announcements', { token: tok.admin, body: { title: 'Cuối tuần có mưa lớn', body: 'Người giao hàng có thể chậm hơn thường lệ.' } }); c.ok('Gửi toàn khu', [200, 201].includes(a.status), `HTTP ${a.status}`); c.ok('Người dùng nhận được', (await api('GET', '/notifications', { token: tok.thuy })).body.data.some((n) => /mưa lớn/.test(JSON.stringify(n)))); });
tc(M9, 'TC_AD_ADM_012', 'Từ khóa cấm chặn bài khi đăng và xuất dữ liệu CSV',
  { pre: 'Đăng nhập quản trị viên.', steps: ['Lưu danh sách từ khóa cấm.', 'Người bán đăng bài chứa từ khóa.', 'Xuất danh sách người dùng ra CSV.'], input: 'bannedKeywords = ["hàng giả"]', expected: ['Lưu thành công.', 'Bài chứa từ khóa bị từ chối (HTTP 422).', 'CSV tải về được (HTTP 200, kiểu text/csv).'] },
  async (c) => { c.eq('Lưu cài đặt → HTTP', (await api('PUT', '/admin/settings', { token: tok.admin, body: { bannedKeywords: ['hàng giả'] } })).status, 200); const r = await api('POST', '/seller/posts', { token: tok.lan, body: { type: 'goods', category: 'Đồ dùng', title: 'Túi hàng giả loại 1', description: 'Túi xách nhìn như thật.', price: 100000, unit: 'cái', area: 'B', fulfillmentModes: ['pickup'], payMethods: ['cash'], areas: ['Bcons'], priceType: 'fixed' } }); c.eq('Đăng bài chứa từ cấm → HTTP', r.status, 422); await api('PUT', '/admin/settings', { token: tok.admin, body: { bannedKeywords: [] } }); const csv = await api('GET', '/admin/export/users', { token: tok.admin, raw: true }); c.eq('Xuất CSV → HTTP', csv.status, 200); c.ok('Kiểu CSV', /csv/.test(csv.type || ''), csv.type); });
tc(M9, 'TC_AD_ADM_013', 'Xem tin nhắn của đơn được ghi vào nhật ký',
  { pre: 'Có đơn đang xử lý.', steps: ['Quản trị xem chi tiết đơn kèm tin nhắn.', 'Xem nhật ký thao tác.'], input: 'chat = 1', expected: ['Xem được tin nhắn (HTTP 200).', 'Nhật ký có dòng order.view_chat.'] },
  async (c) => { const o = (await orderOf(await phoBo())).body.data; c.eq('Xem đơn → HTTP', (await api('GET', `/admin/orders/${o._id}?chat=1`, { token: tok.admin })).status, 200); const a = (await api('GET', '/admin/audit?action=order.view_chat', { token: tok.admin })).body.data; c.ok('Có dấu vết trong nhật ký', a.length >= 1, `${a.length} dòng`); });

// ------------------------------------------------------------------ chạy toàn bộ và ghi kết quả
test('chạy các ca kiểm thử chức năng và ghi kết quả', async () => {
  const out = [];
  for (const k of CASES) {
    const ctx = mkCtx();
    let status = 'Pass'; let error = '';
    try { await k.fn(ctx); } catch (e) { status = 'Fail'; error = String(e.message || e).split('\n')[0].slice(0, 300); }
    out.push({ id: k.id, mod: k.mod, title: k.title, pre: k.pre, steps: k.steps, input: k.input, expected: k.expected, status, actual: ctx.lines, error });
  }
  const dest = path.join(__dirname, '..', '..', 'tools', 'report-gen', 'tc-results.json');
  fs.writeFileSync(dest, JSON.stringify(out, null, 1));
  const fails = out.filter((x) => x.status === 'Fail');
  console.log(`Tổng ${out.length} ca: ${out.length - fails.length} Pass, ${fails.length} Fail`);
  for (const f of fails) console.log(`FAIL ${f.id}: ${f.error}`);
  assert.equal(fails.length, 0, `${fails.length} ca không đạt: ${fails.map((f) => f.id).join(', ')}`);
});
